48	/// Names `@types/react` (and its `React.`-qualified form) recognizes as a
49	/// function-component type. Shared between `extract_props_from_type_annotation`
50	/// (which additionally requires the props argument itself to resolve) and
51	/// `type_annotation_is_fc_family` below (which only needs to know the
52	/// annotation *looked like* one of these) so the two checks can't drift apart.
53	const FC_FAMILY_TYPE_NAMES: &[&str] =
54	    &["FC", "FunctionComponent", "ComponentType", "VFC", "VoidFunctionComponent", "ForwardRefComponent"];
55	
56	/// PascalCase a file's stem for naming an anonymous default-exported
57	/// component that has no identifier of its own — e.g. `button-group.tsx` →
58	/// `ButtonGroup`, `useButton.tsx` → `UseButton`. Splits on any non-alphanumeric
59	/// separator (`-`, `_`, `.`, space) and capitalizes each segment's first
60	/// character. Returns `None` when the path has no usable stem at all (e.g.
61	/// nothing but separators).
62	pub(super) fn pascal_case_from_file_stem(file_path: &Utf8Path) -> Option<String> {
63	    let stem = file_path.file_stem()?;
64	    let mut pascal = String::new();
65	    for segment in stem.split(|c: char| !c.is_alphanumeric()) {
66	        let mut chars = segment.chars();
67	        if let Some(first) = chars.next() {
68	            pascal.extend(first.to_uppercase());
69	            pascal.push_str(chars.as_str());
70	        }
71	    }
72	    (!pascal.is_empty()).then_some(pascal)
73	}
