126	    /// Try to detect: `const Button: FC<ButtonProps> = ({ variant = 'primary' }) => ...`
127	    pub(super) fn try_fc_annotation<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
128	        let type_ann = decl.annotation?;
129	        let init_params = match decl.init.as_ref() {
130	            Some(Expression::ArrowFunctionExpression(afe)) => Some(&*afe.params),
131	            Some(Expression::FunctionExpression(fe)) => Some(&*fe.params),
132	            _ => None,
133	        };
134	        self.extract_props_from_type_annotation(
135	            &type_ann.type_annotation,
136	            name,
137	            decl.span.start,
138	            decl.span.end,
139	            init_params,
140	        )
141	    }
