186	    /// Try to detect: `const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(...)`
187	    pub(super) fn try_forward_ref<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
188	        let init = decl.init.as_ref()?;
189	        let call = match peel_expr(init) {
190	            Expression::CallExpression(ce) => ce,
191	            _ => return None,
192	        };
193	        if !self.is_forward_ref_call(call) {
194	            return None;
195	        }
196	
197	        // forwardRef<RefType, PropsType>(fn) — PropsType is the second type parameter
198	        let type_params = call.type_arguments.as_ref()?;
199	        if type_params.params.len() < 2 {
200	            return None;
201	        }
202	        let props_type = &type_params.params[1];
203	        let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
204	
205	        // The render function is forwardRef's call argument — its first parameter is
206	        // props (the second is `ref`, which never carries destructured defaults we care about).
207	        let render_params = match call.arguments.first() {
208	            Some(Argument::FunctionExpression(fe)) => Some(&fe.params),
209	            Some(Argument::ArrowFunctionExpression(afe)) => Some(&afe.params),
210	            _ => None,
211	        };
212	        let param_defaults = render_params.map(|p| self.extract_param_defaults(p)).unwrap_or_default();
213	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
214	
215	        Some(
216	            ComponentMapping::new(
217	                name.to_owned(),
218	                props_name,
219	                self.file_path.clone(),
220	                decl.span.start,
221	                decl.span.end,
222	                DetectionRule::ForwardRef,
223	            )
224	            .with_props_type_args(type_args)
225	            .with_doc(description, tags)
226	            .with_param_defaults(param_defaults),
227	        )
228	    }
