266	    /// Try to detect: `const Button = anyHOC(function Button(props: ButtonProps) {...})`
267	    pub(super) fn try_hoc_wrapped<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
268	        let init = decl.init.as_ref()?;
269	        let call = match peel_expr(init) {
270	            Expression::CallExpression(ce) => ce,
271	            _ => return None,
272	        };
273	
274	        // First arg should be a function with a typed props param — or a forwardRef() call.
275	        let first_arg = call.arguments.first()?;
276	
277	        // `memo(forwardRef(…))`: the props come from forwardRef's type arguments, or from its render function.
278	        if let Argument::CallExpression(inner) = first_arg {
279	            if !self.is_forward_ref_call(inner) {
280	                return None;
281	            }
282	            // `forwardRef<Ref, Props>(…)` names the props in its second type argument; otherwise the render function's
283	            // first parameter does. A call with one type argument and no function (`forwardRef<Ref>()`) names neither.
284	            let props_type = inner.type_arguments.as_ref().and_then(|type_params| type_params.params.get(1));
285	            let Some(props_type) = props_type else {
286	                let render = inner.arguments.first()?;
287	                return self.mapping_from_typed_function(decl, name, call, render, DetectionRule::ForwardRef);
288	            };
289	            let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
290	            let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
291	            return Some(
292	                ComponentMapping::new(
293	                    name.to_owned(),
294	                    props_name,
295	                    self.file_path.clone(),
296	                    decl.span.start,
297	                    decl.span.end,
298	                    DetectionRule::ForwardRef,
299	                )
300	                .with_props_type_args(type_args)
301	                .with_doc(description, tags),
302	            );
303	        }
304	        let rule = if self.is_forward_ref_call(call) { DetectionRule::ForwardRef } else { DetectionRule::HocWrapper };
305	        self.mapping_from_typed_function(decl, name, call, first_arg, rule)
306	    }
