308	    /// The component a wrapper call builds from a render function whose first parameter names the props type:
309	    /// `memo(function Button(props: ButtonProps) {…})`, and the same inside `memo(forwardRef(…))`. `call` is the outermost
310	    /// wrapper call, whose type arguments may add props (`wrapper.rs`).
311	    fn mapping_from_typed_function<'a>(
312	        &mut self,
313	        decl: &Binding<'_, 'a>,
314	        name: &str,
315	        call: &CallExpression<'a>,
316	        function: &Argument<'a>,
317	        rule: DetectionRule,
318	    ) -> Option<ComponentMapping> {
319	        let (fn_name, params, shape) = match function {
320	            Argument::FunctionExpression(fe) => {
321	                (fe.id.as_ref().map(|id| id.name.as_str()), &fe.params, FunctionShape::of_function(fe))
322	            }
323	            Argument::ArrowFunctionExpression(afe) => (None, &afe.params, FunctionShape::of_arrow(afe)),
324	            _ => return None,
325	        };
326	
327	        // Rules out anonymous utility functions, which aren't components.
328	        if let Some(fn_name_str) = fn_name {
329	            if !is_pascal_case(fn_name_str) {
330	                return None;
331	            }
332	        }
333	
334	        let first_param = params.items.first()?;
335	        let type_ann = first_param.type_annotation.as_ref()?;
336	        // `debounce((q: Row) => …)` and `createSelector((s: State) => …)` have the same shape as `memo(…)`.
337	        if let Err(reason) = renders(&shape, &*self) {
338	            self.decline_reason = Some(format!("'{name}' wraps a typed function that {reason}"));
339	            return None;
340	        }
341	        let (props_name, type_args) = self.extract_type_name_from_type(&type_ann.type_annotation)?;
342	
343	        let param_defaults = self.extract_param_defaults(params);
344	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
345	
346	        let mapping = ComponentMapping::new(
347	            name.to_owned(),
348	            props_name,
349	            self.file_path.clone(),
350	            decl.span.start,
351	            decl.span.end,
352	            rule,
353	        )
354	        .with_props_type_args(type_args)
355	        .with_doc(description, tags)
356	        .with_param_defaults(param_defaults);
357	        // `factory<Payload>((props: P) => …)`: a generic wrapper's result type can add props, as in `wrapper.rs`.
358	        Some(match self.wrapper_callee(call) {
359	            Some(callee) => mapping.with_wrapper_callee(callee),
360	            None => mapping,
361	        })
362	    }
363	
364	    /// Try to detect declared `ForwardRefExoticComponent<Props>` and `MemoExoticComponent<(props: Props) => JSX>` values.
365	    ///
366	    /// Common in .d.ts files — no initializer, just a type annotation.
367	    pub(super) fn try_exotic_component_decl<'a>(
368	        &mut self,
369	        decl: &VariableDeclarator<'a>,
370	        name: &str,
371	    ) -> Option<ComponentMapping> {
372	        let type_ann = decl.type_annotation.as_ref()?;
373	        let ct = self.ts_type_to_collected(&type_ann.type_annotation);
374	
375	        let is_react_type = |name: &str, expected: &str| {
376	            name == expected
377	                || name.rsplit_once('.').is_some_and(|(prefix, suffix)| {
378	                    suffix == expected
379	                        && (prefix == "React"
380	                            || self.data.imports.iter().any(|binding| {
381	                                binding.local_name == prefix
382	                                    && binding.exported_name == "*"
383	                                    && binding.specifier == "react"
384	                            }))
385	                })
386	        };
387	        let exotic_args = |ty: &crate::types::CollectedType| match ty {
388	            crate::types::CollectedType::Named { name, args } if is_react_type(name, "ForwardRefExoticComponent") => {
389	                Some((args.clone(), false))
390	            }
391	            crate::types::CollectedType::Named { name, args } if is_react_type(name, "MemoExoticComponent") => {
392	                Some((args.clone(), true))
393	            }
394	            _ => None,
395	        };
396	        let (args, memoized) = match &ct {
397	            crate::types::CollectedType::Intersection(members) => members.iter().find_map(exotic_args),
398	            other => exotic_args(other),
399	        }?;
400	
401	        let first_arg = args.first()?;
402	
403	        // RefAttributes is metadata on the value, not a prop base. Keep every other member: declaration generators
404	        // often write several props objects into one ForwardRefExoticComponent argument.
405	        let props_type = match first_arg {
406	            crate::types::CollectedType::Function { params, .. } if memoized => params.first()?.clone(),
407	            _ if memoized => return None,
408	            crate::types::CollectedType::Intersection(members) => {
409	                let mut props: Vec<_> = members
410	                    .iter()
411	                    .filter(|member| {
412	                        !matches!(member, crate::types::CollectedType::Named { name, .. }
413	                            if is_react_type(name, "RefAttributes"))
414	                    })
415	                    .cloned()
416	                    .collect();
417	                match props.len() {
418	                    0 => return None,
419	                    1 => props.remove(0),
420	                    _ => crate::types::CollectedType::Intersection(props),
421	                }
422	            }
423	            other => other.clone(),
424	        };
425	
426	        let (props_name, props_args) = match props_type {
427	            crate::types::CollectedType::Named { name, args } => (name, args),
428	            props => {
429	                let name = format!("__anon_{}", self.data.type_aliases.len());
430	                let key = self.scoped_key(&name);
431	                self.data.type_aliases.insert(
432	                    key,
433	                    crate::types::CollectedTypeAlias::Passthrough { target: props, file_path: self.file_path.clone() },
434	                );
435	                (name.into(), vec![])
436	            }
437	        };
438	
439	        Some(
440	            ComponentMapping::new(
441	                name.to_owned(),
442	                props_name,
443	                self.file_path.clone(),
444	                decl.span.start,
445	                decl.span.end,
446	                if memoized { DetectionRule::MemoExoticDecl } else { DetectionRule::ForwardRefExoticDecl },
447	            )
448	            .with_props_type_args(props_args)
449	            .with_doc(self.find_jsdoc(decl.span.start), BTreeMap::new())
450	            .with_param_defaults(rustc_hash::FxHashMap::default()),
451	        )
452	    }
