454	    /// A dependency can publish a component as `declare const Tab: (props: TabProps) => ReactElement | null`.
455	    pub(super) fn try_declared_callable_component<'a>(
456	        &mut self,
457	        decl: &VariableDeclarator<'a>,
458	        name: &str,
459	    ) -> Option<ComponentMapping> {
460	        let annotation = &decl.type_annotation.as_ref()?.type_annotation;
461	        let (params, return_type, type_parameters) = if let TSType::TSFunctionType(function) = annotation {
462	            (function.params.as_ref(), function.return_type.as_ref(), function.type_parameters.as_deref())
463	        } else if let TSType::TSTypeLiteral(literal) = annotation {
464	            let mut calls = literal.members.iter().filter_map(|member| match member {
465	                TSSignature::TSCallSignatureDeclaration(call) => Some(call.as_ref()),
466	                TSSignature::TSIndexSignature(_)
467	                | TSSignature::TSPropertySignature(_)
468	                | TSSignature::TSConstructSignatureDeclaration(_)
469	                | TSSignature::TSMethodSignature(_) => None,
470	            });
471	            let call = calls.next()?;
472	            if calls.next().is_some() {
473	                return None;
474	            }
475	            (call.params.as_ref(), call.return_type.as_deref()?, call.type_parameters.as_deref())
476	        } else {
477	            return None;
478	        };
479	        let [parameter] = params.items.as_slice() else { return None };
480	        let return_type = self.ts_type_to_collected(&return_type.type_annotation);
481	        let is_element = |name: &str| {
482	            matches!(name, "React.ReactElement" | "React.JSX.Element" | "JSX.Element")
483	                || name.strip_suffix(".JSX.Element").is_some_and(|namespace| {
484	                    self.data.imports.iter().any(|binding| {
485	                        binding.local_name == namespace
486	                            && binding.exported_name == "*"
487	                            && matches!(binding.specifier.as_str(), "react/jsx-runtime" | "react/jsx-dev-runtime")
488	                    })
489	                })
490	                || self.data.imports.iter().any(|binding| {
491	                    binding.local_name == name
492	                        && binding.exported_name == "ReactElement"
493	                        && binding.specifier == "react"
494	                })
495	        };
496	        let returns_element = |ty: &crate::types::CollectedType| match ty {
497	            crate::types::CollectedType::Named { name, .. } => is_element(name),
498	            crate::types::CollectedType::Union(members) => members.iter().any(|member| {
499	                if let crate::types::CollectedType::Named { name, .. } = member {
500	                    is_element(name)
501	                } else {
502	                    false
503	                }
504	            }),
505	            _ => false,
506	        };
507	        if !returns_element(&return_type) {
508	            return None;
509	        }
510	        let (props_name, mut props_args) =
511	            self.extract_type_name_from_type(&parameter.type_annotation.as_ref()?.type_annotation)?;
512	        let type_params: Vec<crate::types::TypeName> = type_parameters
513	            .map(|declaration| declaration.params.iter().map(|param| param.name.name.as_str().into()).collect())
514	            .unwrap_or_default();
515	        if props_name.starts_with("__anon_") && !type_params.is_empty() {
516	            self.data.type_alias_params.insert(self.scoped_key(&props_name), type_params.clone());
517	            props_args = type_params
518	                .iter()
519	                .map(|name| crate::types::CollectedType::Named { name: name.clone(), args: Vec::new() })
520	                .collect();
521	        }
522	        let mut mapping = ComponentMapping::new(
523	            name.to_owned(),
524	            props_name,
525	            self.file_path.clone(),
526	            decl.span.start,
527	            decl.span.end,
528	            DetectionRule::FunctionDeclaration,
529	        )
530	        .with_props_type_args(props_args)
531	        .with_doc(self.find_jsdoc(decl.span.start), BTreeMap::new());
532	        mapping.type_params = type_params;
533	        Some(mapping)
534	    }
535	
536	    /// Try to detect: `export default function(props: Props) { ... }` — an
537	    /// anonymous default-exported function component, common in Next.js page
538	    /// files. There's no identifier to name it after, so the PascalCased
539	    /// file stem is used instead. Mirrors Pattern 4's
540	    /// (`visit_function`'s named-function handling) exact contract: a
541	    /// missing type annotation is a flagged skip, but zero declared params
542	    /// at all is silent — same as the named-function sibling.
543	    pub(super) fn try_anonymous_default_export_component<'a>(&mut self, func: &Function<'a>) {
544	        let Some(name) = pascal_case_from_file_stem(&self.file_path) else { return };
545	
546	        let Some(first_param) = func.params.items.first() else { return };
547	        let Some(type_ann) = &first_param.type_annotation else {
548	            self.record_skip(
549	                DiagnosticCode::SkippedCandidate,
550	                format!("'{name}' is an anonymous default-exported function component with an untyped first param"),
551	                first_param.span,
552	            );
553	            return;
554	        };
555	        let Some((props_name, type_args)) = self.extract_type_name_from_type(&type_ann.type_annotation) else {
556	            self.record_skip(
557	                DiagnosticCode::SkippedCandidate,
558	                format!(
559	                    "'{name}' is an anonymous default-exported function component whose first param's type \
560	                     annotation isn't a recognizable props type reference"
561	                ),
562	                type_ann.span,
563	            );
564	            return;
565	        };
566	
567	        let (description, tags) = self.find_jsdoc_with_tags(func.span.start);
568	        let param_defaults = self.extract_param_defaults(&func.params);
569	        self.data.component_mappings.push(
570	            ComponentMapping::new(
571	                name,
572	                props_name,
573	                self.file_path.clone(),
574	                func.span.start,
575	                func.span.end,
576	                DetectionRule::AnonymousDefaultExport,
577	            )
578	            .with_props_type_args(type_args)
579	            .with_doc(description, tags)
580	            .with_param_defaults(param_defaults),
581	        );
582	    }
583	
584	    /// True when `class`'s `extends` clause is `Component`/`PureComponent`
585	    /// (bare or `React.`-qualified). Returns the matched bare name for use in
586	    /// diagnostic messages.
587	    pub(super) fn super_class_is_component_family<'a>(&self, class: &Class<'a>) -> Option<&'static str> {
588	        let super_name = self.expression_to_ident_name(&class.heritage.as_ref()?.expression);
589	        let bare = super_name.strip_prefix("React.").unwrap_or(&super_name);
590	        match bare {
591	            "Component" => Some("Component"),
592	            "PureComponent" => Some("PureComponent"),
593	            _ => None,
594	        }
595	    }
596	
597	    /// Try to detect: `class Button extends React.Component<Props> { ... }`
598	    /// (or bare `Component`/`PureComponent`). Shared by both a named
599	    /// `ClassDeclaration` (called directly from `visit_class`) and an
600	    /// anonymous `ClassExpression` assigned to a variable (via
601	    /// `try_class_expression_wrapped` below). Silent on every failure path,
602	    /// mirroring `try_fc_annotation`/`try_forward_ref`/`try_hoc_wrapped`'s own
603	    /// contract — callers decide whether and how to surface a diagnostic.
604	    pub(super) fn try_class_component<'a>(&mut self, class: &Class<'a>, name: &str) -> Option<ComponentMapping> {
605	        self.super_class_is_component_family(class)?;
606	        let type_args = class.heritage.as_ref()?.type_arguments.as_ref()?;
607	        let props_type = type_args.params.first()?;
608	        let (props_name, props_type_args) = self.extract_type_name_from_type(props_type)?;
609	        let (description, tags) = self.find_jsdoc_with_tags(class.span.start);
610	        Some(
611	            ComponentMapping::new(
612	                name.to_owned(),
613	                props_name,
614	                self.file_path.clone(),
615	                class.span.start,
616	                class.span.end,
617	                DetectionRule::ClassComponent,
618	            )
619	            .with_props_type_args(props_type_args)
620	            .with_doc(description, tags)
621	            .with_param_defaults(rustc_hash::FxHashMap::default()),
622	        )
623	    }
624	
625	    /// Try to detect: `const Button = class extends React.Component<Props> { ... }`
626	    /// — an anonymous class expression assigned to a PascalCase binding. Only
627	    /// fires when the class expression has no name of its own; a self-named
628	    /// one (`class Button extends ...`) is instead picked up directly by
629	    /// `visit_class` under its own identifier, avoiding a duplicate mapping
630	    /// under both names.
631	    pub(super) fn try_class_expression_wrapped<'a>(
632	        &mut self,
633	        decl: &Binding<'_, 'a>,
634	        name: &str,
635	    ) -> Option<ComponentMapping> {
636	        let init = decl.init.as_ref()?;
637	        let Expression::ClassExpression(class) = init else { return None };
638	        if class.id.is_some() {
639	            return None;
640	        }
641	        self.try_class_component(class, name)
642	    }
643	
644	    /// True when `decl`'s type annotation (after peeling parens) is a bare
645	    /// reference to one of the FC-family type names, regardless of whether
646	    /// its props type argument is itself extractable.
647	    ///
648	    /// Used by the no-initializer Pattern 5 diagnostic guard in `visit.rs`:
649	    /// `try_fc_annotation` already runs unconditionally for every PascalCase
650	    /// declarator (init or no init) and would have produced a mapping had the
651	    /// props argument resolved, so reaching this check with no mapping means
652	    /// the props argument specifically was the unrecognized part — an exotic
653	    /// `TSType` shape `extract_type_name_from_type` doesn't match — not that
654	    /// the declaration isn't FC-shaped at all.
655	    pub(super) fn type_annotation_is_fc_family<'a>(&self, decl: &VariableDeclarator<'a>) -> bool {
656	        fn peel_parens<'t, 'a>(ty: &'t TSType<'a>) -> &'t TSType<'a> {
657	            match ty {
658	                TSType::TSParenthesizedType(p) => peel_parens(&p.type_annotation),
659	                other => other,
660	            }
661	        }
662	        let Some(type_ann) = decl.type_annotation.as_ref() else { return false };
663	        let TSType::TSTypeReference(tr) = peel_parens(&type_ann.type_annotation) else { return false };
664	        let type_name = self.extract_type_ref_name(tr);
665	        let bare_name = type_name.strip_prefix("React.").unwrap_or(&type_name);
666	        FC_FAMILY_TYPE_NAMES.contains(&bare_name)
667	    }
668	
669	    /// Rename an already-collected component mapping to its real public export name
670	    /// when the mapping's own identifier is immediately wrapped by an *unrecognized*
671	    /// call and reassigned to a new binding — e.g. Headless UI's real
672	    /// `export let ListboxButton = forwardRefWithAs(ButtonFn) as X`. `forwardRefWithAs`
673	    /// is a library-defined wrapper, not `React.forwardRef` itself, so `try_forward_ref`
674	    /// never matches it; meanwhile `ButtonFn` — a standalone top-level function
675	    /// declaration — was already independently collected as its own component by the
676	    /// `visit_function` Pattern 4 check, under the wrong (inner, implementation-only)
677	    /// name. Without this, the real export name never appears at all.
678	    ///
679	    /// Also handles the same rename with no wrapper call at all — a bare passthrough
680	    /// alias, `const Button = InternalCompoundedButton;` (optionally `as X`), antd's
681	    /// real `Button` export shape.
682	    ///
683	    /// Clones the matched mapping under the new name rather than renaming it in
684	    /// place: a second, different alias to the same base
685	    /// (`const A = Base; const Bcopy = Base;`) is a genuinely distinct exported
686	    /// binding, not the same rename twice, and renaming in place would make the
687	    /// base unfindable for that second alias — silently dropping it. The base's
688	    /// own (implementation-only) name is filtered out of the final output in
689	    /// `finish()` via `aliased_away`.
690	    pub(super) fn try_rename_identifier_wrapped_component<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> bool {
691	        let Some(init) = decl.init.as_ref() else { return false };
692	        let (inner_name, call) = match peel_expr(init) {
693	            Expression::CallExpression(call) => match call.arguments.first() {
694	                Some(Argument::Identifier(id)) => (id.name.as_str(), Some(&**call)),
695	                _ => return false,
696	            },
697	            Expression::Identifier(id) => (id.name.as_str(), None),
698	            _ => return false,
699	        };
700	
701	        // The component it receives is not the one it builds when a type argument names the props.
702	        if call.is_some_and(|call| self.call_names_props_type(call)) {
703	            return false;
704	        }
705	        let Some(base) = self.data.component_mappings.iter().find(|m| m.component_name == inner_name) else {
706	            return false;
707	        };
708	        // `getDisplayName(Card)` has the same shape as `memo(Card)` but returns a string; only a call that follows the
709	        // component-wrapper conventions produces a component.
710	        if let Some(call) = call {
711	            if !super::evidence::Scope::is_react_wrapper(&*self, call) && !is_component_wrapper_call(call) {
712	                self.decline_reason = Some(format!(
713	                    "'{name}' passes component '{inner_name}' to a call that does not look like a component wrapper"
714	                ));
715	                return false;
716	            }
717	        }
718	        let mut alias = base.clone();
719	        // `forwardRef(Inner)` makes a component that takes a `ref` even when `Inner` is a plain typed function.
720	        if call.is_some_and(|call| self.is_forward_ref_call(call)) {
721	            alias.rule = DetectionRule::ForwardRef;
722	        }
723	        alias.component_name = name.to_owned();
724	        self.data.component_mappings.push(alias);
725	        self.aliased_away.insert(inner_name.into());
726	        true
727	    }
728	
729	    /// Record `const X = Imported.Member` as a component whose props are the imported member's
730	    /// (`ComponentProps<typeof Imported.Member>`), when `Imported` is an import binding and `Member` is PascalCase.
731	    pub(super) fn try_record_imported_member_alias<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> bool {
732	        let Some(init) = decl.init.as_ref() else { return false };
733	        let Expression::StaticMemberExpression(member) = peel_expr(init) else { return false };
734	        let Expression::Identifier(object) = &member.object else { return false };
735	        let property = member.property.name.as_str();
736	        if !self.imported_names.contains(object.name.as_str()) || !is_pascal_case(property) {
737	            return false;
738	        }
739	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
740	        self.data.component_mappings.push(
741	            ComponentMapping::new(
742	                name.to_owned(),
743	                "ComponentProps".into(),
744	                self.file_path.clone(),
745	                decl.span.start,
746	                decl.span.end,
747	                DetectionRule::ImportedMemberAlias,
748	            )
749	            .with_props_type_args(vec![crate::types::CollectedType::TypeOf(
750	                format!("{}.{property}", object.name).into(),
751	            )])
752	            .with_doc(description, tags),
753	        );
754	        true
755	    }
756	
757	    /// Whether `call` makes a component that takes a `ref` whatever its props type declares: React's `forwardRef` however
758	    /// it is imported or spelled, or another module's own `forwardRef` (React Aria's).
759	    fn is_forward_ref_call(&self, call: &CallExpression<'_>) -> bool {
760	        if self.react_api(&call.callee) == Some(ReactApi::ForwardRef) {
761	            return true;
762	        }
763	        let name = match peel_expr(&call.callee) {
764	            Expression::Identifier(id) => id.name.as_str(),
765	            Expression::StaticMemberExpression(member) => member.property.name.as_str(),
766	            _ => return false,
767	        };
768	        name == "forwardRef" && self.react_api(&call.callee).is_none()
769	    }
770	
771	    /// Extract the callee name of a call expression (simple ident or member expr).
772	    pub(super) fn extract_callee_name<'a>(&self, call: &CallExpression<'a>) -> Option<String> {
773	        match &call.callee {
774	            Expression::Identifier(id) => Some(id.name.as_str().to_owned()),
775	            Expression::StaticMemberExpression(me) => {
776	                Some(format!("{}.{}", self.expression_to_ident_name(&me.object), me.property.name.as_str()))
777	            }
778	            _ => None,
779	        }
780	    }
781	}
782	
783	/// Whether a call wrapping a component returns a component, by React's own wrappers and the ecosystem's conventions:
784	/// `memo`, anything named like `forwardRef`, `withX(...)` higher-order components, `createXComponent(...)` factories,
785	/// `observer`, and curried wrappers such as `connect(...)(Component)` or `styled(...)(Component)`.
786	pub(super) fn is_component_wrapper_call(call: &CallExpression<'_>) -> bool {
787	    // `(forwardRef as forwardRefType)(X)` is React Aria's spelling of `forwardRef(X)`.
788	    let callee = match peel_expr(&call.callee) {
789	        Expression::Identifier(id) => id.name.as_str(),
790	        Expression::StaticMemberExpression(m) => m.property.name.as_str(),
791	        Expression::CallExpression(_) => return true,
792	        _ => return false,
793	    };
794	    let lower = callee.to_ascii_lowercase();
795	    callee == "memo"
796	        || callee == "observer"
797	        || lower.contains("forwardref")
798	        || callee.contains("Component")
799	        || (callee.len() > 4 && callee.starts_with("with") && callee[4..].starts_with(|c: char| c.is_ascii_uppercase()))
800	}
