278	    fn visit_variable_declaration(&mut self, node: &VariableDeclaration<'a>) {
279	        for declarator in &node.declarations {
280	            self.try_collect_const_enum(declarator);
281	            self.try_collect_const_array(declarator);
282	            // Collect variant bags (a call with a `variants` map of maps: cva, tv, recipes) for all file types
283	            if let BindingPattern::BindingIdentifier(id) = &declarator.id {
284	                let name = id.name.as_str().to_owned();
285	                self.try_collect_variant_bag(declarator, &name);
286	                self.record_object_assign_declarator(&name, declarator.init.as_ref());
287	                if self.function_depth == 0 {
288	                    self.try_record_cast_component_alias(declarator, &name);
289	                }
290	                if self.function_depth == 0 && node.kind.is_const() {
291	                    if let Some(Expression::Identifier(target)) =
292	                        declarator.init.as_ref().map(super::component::peel_expr)
293	                    {
294	                        self.pending_function_aliases.push((name, target.name.as_str().to_owned()));
295	                    }
296	                }
297	            }
298	            if self.is_tsx && self.function_depth > 0 {
299	                if let Some(name) = self.extract_pascal_name(declarator) {
300	                    if self.detect_component(&Binding::of(declarator), &name).is_some() {
301	                        self.skip_local_component(&name, declarator.span);
302	                    }
303	                }
304	            } else if self.is_tsx {
305	                if let Some(name) = self.extract_pascal_name(declarator) {
306	                    self.decline_reason = None;
307	                    let binding = Binding::of(declarator);
308	                    if let Some(mapping) = self.detect_component(&binding, &name) {
309	                        self.data.component_mappings.push(mapping);
310	                        continue;
311	                    }
312	                    // try_rename_identifier_wrapped_component is itself a give-up-quietly
313	                    // path (a bare/wrapped identifier re-binding, not a props-bearing
314	                    // component candidate) — only record a skip when even that finds
315	                    // nothing, so plain aliasing (`const Button = InternalButton;`)
316	                    // doesn't spuriously report as an unsupported candidate. Also skip
317	                    // no-initializer declarations (`declare var Date: DateConstructor`) —
318	                    // those are ambient type-only bindings handled by Pattern 5 below
319	                    // (or legitimately not components at all), not failed candidates.
320	                    if declarator.init.is_some()
321	                        && !self.try_rename_identifier_wrapped_component(&binding, &name)
322	                        && !self.try_record_wrapper_call(&binding, &name)
323	                        && !self.try_record_tagged_factory(&binding, &name)
324	                        && !self.try_record_imported_member_alias(&binding, &name)
325	                    {
326	                        let message = self.decline_reason.take().unwrap_or_else(|| {
327	                            format!(
328	                                "'{name}' is a PascalCase binding but matched no known component pattern \
329	                                 (FC annotation, forwardRef, HOC wrapper, or identifier alias)"
330	                            )
331	                        });
332	                        self.record_skip(DiagnosticCode::SkippedCandidate, message, declarator.span);
333	                    }
334	                }
335	            }
336	            self.record_body_defaults(declarator);
337	            // Pattern 5: declare const Button: React.ForwardRefExoticComponent<ButtonProps & RefAttributes<E>>
338	            // Common in .d.ts files — no initializer, just a type annotation
339	            if declarator.init.is_none() {
340	                if node.kind.is_const() {
341	                    self.record_declared_value_type(declarator);
342	                }
343	                let name = self.extract_pascal_name(declarator).or_else(|| {
344	                    let path = self.file_path.as_str();
345	                    if ![".d.ts", ".d.mts", ".d.cts"].iter().any(|suffix| path.ends_with(suffix)) {
346	                        return None;
347	                    }
348	                    match &declarator.id {
349	                        BindingPattern::BindingIdentifier(id) => Some(id.name.as_str().to_owned()),
350	                        _ => None,
351	                    }
352	                });
353	                if let Some(name) = name {
354	                    if let Some(mapping) = self
355	                        .try_exotic_component_decl(declarator, &name)
356	                        .or_else(|| self.try_declared_callable_component(declarator, &name))
357	                    {
358	                        self.data.component_mappings.push(mapping);
359	                    } else if self.type_annotation_is_fc_family(declarator) {
360	                        // try_fc_annotation already ran unconditionally above and found
361	                        // nothing — the annotation is FC-shaped but its props type
362	                        // argument is an exotic TSType this extractor doesn't match.
363	                        self.record_skip(
364	                            DiagnosticCode::SkippedCandidate,
365	                            format!(
366	                                "'{name}' is a PascalCase declaration with an FC-family type annotation whose \
367	                                 props type argument isn't a recognizable type"
368	                            ),
369	                            declarator.span,
370	                        );
371	                    }
372	                }
373	            }
374	        }
375	        walk::walk_variable_declaration(self, node);
376	    }
