378	    fn visit_arrow_function_expression(&mut self, arrow: &ArrowFunctionExpression<'a>) {
379	        self.record_function_type_params(arrow.span, arrow.type_parameters.as_deref());
380	        self.props_params.push((first_param_name(&arrow.params), arrow.span.start, arrow.span.end));
381	        walk::walk_arrow_function_expression(self, arrow);
382	        self.props_params.pop();
383	    }
