385	    fn visit_function(&mut self, func: &Function<'a>, flags: ScopeFlags) {
386	        self.record_function_result(func);
387	        self.record_function_type_params(func.span, func.type_parameters.as_deref());
388	        self.props_params.push((first_param_name(&func.params), func.span.start, func.span.end));
389	        // Pattern 4: `function Button(props: ButtonProps) { ... }`
390	        if self.is_tsx {
391	            if let Some(id) = &func.id {
392	                let name = id.name.as_str();
393	                let declaration =
394	                    matches!(func.r#type, FunctionType::FunctionDeclaration | FunctionType::TSDeclareFunction);
395	                if is_pascal_case(name) && declaration && self.function_depth > 0 {
396	                    let typed = func.params.items.first().is_some_and(|p| p.type_annotation.is_some());
397	                    let shape = super::evidence::FunctionShape::of_function(func);
398	                    if typed && super::evidence::renders(&shape, &*self).is_ok() {
399	                        self.skip_local_component(name, func.span);
400	                    }
401	                } else if is_pascal_case(name) && declaration {
402	                    if let Some(first_param) = func.params.items.first() {
403	                        if let Some(type_ann) = &first_param.type_annotation {
404	                            if let Err(reason) =
405	                                super::evidence::renders(&super::evidence::FunctionShape::of_function(func), &*self)
406	                            {
407	                                // A `declare function` with a non-element return type is an API declaration, not a
408	                                // component that failed to qualify: lib.dom.d.ts alone declares dozens of them.
409	                                if func.r#type == FunctionType::FunctionDeclaration {
410	                                    self.record_skip(
411	                                        DiagnosticCode::SkippedCandidate,
412	                                        format!("'{name}' takes a typed props parameter but {reason}"),
413	                                        func.span,
414	                                    );
415	                                }
416	                            } else if let Some((props_name, type_args)) =
417	                                self.extract_type_name_from_type(&type_ann.type_annotation)
418	                            {
419	                                if func.params.items.len() > 1 {
420	                                    self.takes_a_second_parameter.insert(name.into());
421	                                }
422	                                let (description, tags) = self.find_jsdoc_with_tags(func.span.start);
423	                                let param_defaults = self.extract_param_defaults(&func.params);
424	                                self.data.component_mappings.push(
425	                                    ComponentMapping::new(
426	                                        name.to_owned(),
427	                                        props_name,
428	                                        self.file_path.clone(),
429	                                        func.span.start,
430	                                        func.span.end,
431	                                        DetectionRule::FunctionDeclaration,
432	                                    )
433	                                    .with_props_type_args(type_args)
434	                                    .with_doc(description, tags)
435	                                    .with_param_defaults(param_defaults),
436	                                );
437	                            } else {
438	                                self.record_skip(
439	                                    DiagnosticCode::SkippedCandidate,
440	                                    format!(
441	                                        "'{name}' is a PascalCase function declaration whose first param's type \
442	                                         annotation isn't a recognizable props type reference"
443	                                    ),
444	                                    type_ann.span,
445	                                );
446	                            }
447	                        } else {
448	                            self.record_skip(
449	                                DiagnosticCode::SkippedCandidate,
450	                                format!("'{name}' is a PascalCase function declaration with an untyped first param"),
451	                                first_param.span,
452	                            );
453	                        }
454	                    }
455	                }
456	            }
457	        }
458	        walk::walk_function(self, func, flags);
459	        self.props_params.pop();
460	    }
