533	    fn visit_export_default_declaration(&mut self, node: &ExportDefaultDeclaration<'a>) {
534	        // The default export's local name; an anonymous one is named after its file below.
535	        let local = match &node.declaration {
536	            ExportDefaultDeclarationKind::FunctionDeclaration(func) => func.id.as_ref().map(|id| id.name.as_str()),
537	            ExportDefaultDeclarationKind::ClassDeclaration(class) => class.id.as_ref().map(|id| id.name.as_str()),
538	            kind => match kind.as_expression().map(super::component::peel_expr) {
539	                Some(Expression::Identifier(id)) => Some(id.name.as_str()),
540	                _ => None,
541	            },
542	        };
543	        match local {
544	            Some(name) => {
545	                self.record_exported_local(name);
546	                // `export default Tooltip`: the module's default is `Tooltip`, which `finish` turns into a re-export
547	                // when it is an import, as `export { Tooltip as default }` is.
548	                self.pending_local_exports.push((self.data.exports.len(), name.to_owned()));
549	                self.data.exports.push(LexedExport::LocalDeclaration {
550	                    name: "default".to_owned(),
551	                    is_type_only: false,
552	                    declared_as: Some(name.to_owned()),
553	                });
554	            }
555	            None => {
556	                if let Some(name) = super::component::pascal_case_from_file_stem(&self.file_path) {
557	                    self.record_exported_local(&name);
558	                }
559	            }
560	        }
561	        // An anonymous default export has no binding name, so the component is named after its file, as
562	        // `try_anonymous_default_export_component` already does for `export default function(props: Props) {}`.
563	        if self.is_tsx {
564	            match &node.declaration {
565	                ExportDefaultDeclarationKind::FunctionDeclaration(func) if func.id.is_none() => {
566	                    self.try_anonymous_default_export_component(func);
567	                }
568	                ExportDefaultDeclarationKind::ClassDeclaration(class) if class.id.is_none() => {
569	                    if let Some(name) = super::component::pascal_case_from_file_stem(&self.file_path) {
570	                        if let Some(mapping) = self.try_class_component(class, &name) {
571	                            self.data.component_mappings.push(mapping);
572	                        }
573	                    }
574	                }
575	                // `export default (props: P) => …`, `export default memo(function Badge(…))`,
576	                // `export default forwardRef<El, P>(…)`: an expression, so the declarator rules apply.
577	                kind => {
578	                    if let (Some(expr), Some(name)) =
579	                        (kind.as_expression(), super::component::pascal_case_from_file_stem(&self.file_path))
580	                    {
581	                        let binding = Binding { init: Some(expr), span: node.span, annotation: None };
582	                        self.decline_reason = None;
583	                        if let Some(mapping) = self.detect_component(&binding, &name) {
584	                            self.data.component_mappings.push(mapping);
585	                        } else {
586	                            self.try_record_wrapper_call(&binding, &name);
587	                        }
588	                    }
589	                }
590	            }
591	        }
592	        walk::walk_export_default_declaration(self, node);
593	    }
594	
595	    fn visit_expression_statement(&mut self, node: &ExpressionStatement<'a>) {
596	        self.try_scan_display_name(node);
597	        self.try_scan_default_props(node);
598	        self.record_member_assignment(node);
599	        if self.is_tsx {
600	            self.try_scan_object_assign_sub_components(node);
601	        }
602	        walk::walk_expression_statement(self, node);
603	    }
604	}
