13	/// Peel any wrapping `as X` casts, `satisfies X` checks or `!` assertions down to the real
14	/// expression underneath. Needed because component libraries commonly cast a
15	/// forwardRef/HOC call to a hand-rolled wrapper type instead of relying on
16	/// `@types/react`'s own generics (Fluent UI's own source notes this is
17	/// "required due to lack of distributive union to support unions on
18	/// @types/react"); `satisfies` (TS 4.9+) is the modern equivalent of the same
19	/// pattern and must be peeled the same way.
20	pub(super) fn peel_expr<'a, 'b>(expr: &'b Expression<'a>) -> &'b Expression<'a> {
21	    let mut expr = expr;
22	    loop {
23	        expr = match expr {
24	            Expression::ParenthesizedExpression(parenthesized) => &parenthesized.expression,
25	            Expression::TSAsExpression(as_expr) => &as_expr.expression,
26	            Expression::TSSatisfiesExpression(sat_expr) => &sat_expr.expression,
27	            Expression::TSNonNullExpression(non_null) => &non_null.expression,
28	            _ => return expr,
29	        };
30	    }
31	}
