33	/// What the component rules read from a binding: its initializer, span and type annotation. Built from a
34	/// `const X = ...` declarator or from an `export default ...` expression, so both go through the same rules.
35	#[derive(Clone, Copy)]
36	pub(super) struct Binding<'b, 'a> {
37	    pub(super) init: Option<&'b Expression<'a>>,
38	    pub(super) span: oxc_span::Span,
39	    pub(super) annotation: Option<&'b TSTypeAnnotation<'a>>,
40	}
