42	impl<'b, 'a> Binding<'b, 'a> {
43	    pub(super) fn of(decl: &'b VariableDeclarator<'a>) -> Self {
44	        Self { init: decl.init.as_ref(), span: decl.span, annotation: decl.type_annotation.as_deref() }
45	    }
46	}
