75	impl<'src> SourceDataCollector<'src> {
76	    /// An asserted React component alias can replace the inner component's props before the alias is exported.
77	    pub(super) fn try_record_cast_component_alias<'a>(&mut self, decl: &VariableDeclarator<'a>, name: &str) {
78	        let Some(Expression::TSAsExpression(assertion)) = decl.init.as_ref() else { return };
79	        let Expression::Identifier(inner) = assertion.expression.without_parentheses() else { return };
80	        let has_base = self.data.component_mappings.iter().any(|mapping| mapping.component_name == inner.name.as_str());
81	        if !has_base {
82	            return;
83	        }
84	        let TSType::TSTypeReference(reference) = &assertion.type_annotation else { return };
85	        let type_name = self.extract_type_ref_name(reference);
86	        let bare = type_name.strip_prefix("React.").unwrap_or(&type_name);
87	        if !matches!(bare, "ForwardRefExoticComponent" | "FunctionComponent" | "FC" | "ComponentType") {
88	            return;
89	        }
90	        let Some(props) = reference.type_arguments.as_ref().and_then(|args| args.params.first()) else { return };
91	        let alias_name = format!("__{name}CastProps{}", decl.span.start);
92	        let alias_key = self.scoped_key(&alias_name);
93	        let target = self.ts_type_to_collected(props);
94	        self.data
95	            .type_aliases
96	            .insert(alias_key, CollectedTypeAlias::Passthrough { target, file_path: self.file_path.clone() });
97	        self.cast_component_aliases.insert(name.into(), (inner.name.as_str().to_owned(), alias_name.into()));
98	    }
