102	    /// Try to extract a PascalCase name from a VariableDeclarator's binding.
103	    pub(super) fn extract_pascal_name<'a>(&self, decl: &VariableDeclarator<'a>) -> Option<String> {
104	        match &decl.id {
105	            BindingPattern::BindingIdentifier(id) => {
106	                let name = id.name.as_str();
107	                if is_pascal_case(name) {
108	                    Some(name.to_owned())
109	                } else {
110	                    None
111	                }
112	            }
113	            _ => None,
114	        }
115	    }
116	
117	    /// The ordered rules for a binding whose initializer may be a component; the first that matches wins.
118	    pub(super) fn detect_component<'a>(&mut self, binding: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
119	        self.try_fc_annotation(binding, name)
120	            .or_else(|| self.try_forward_ref(binding, name))
121	            .or_else(|| self.try_hoc_wrapped(binding, name))
122	            .or_else(|| self.try_class_expression_wrapped(binding, name))
123	            .or_else(|| self.try_typed_function_expression(binding, name))
124	    }
