126	    /// Try to detect: `const Button: FC<ButtonProps> = ({ variant = 'primary' }) => ...`
127	    pub(super) fn try_fc_annotation<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
128	        let type_ann = decl.annotation?;
129	        let init_params = match decl.init.as_ref() {
130	            Some(Expression::ArrowFunctionExpression(afe)) => Some(&*afe.params),
131	            Some(Expression::FunctionExpression(fe)) => Some(&*fe.params),
132	            _ => None,
133	        };
134	        self.extract_props_from_type_annotation(
135	            &type_ann.type_annotation,
136	            name,
137	            decl.span.start,
138	            decl.span.end,
139	            init_params,
140	        )
141	    }
142	
143	    pub(super) fn extract_props_from_type_annotation<'a>(
144	        &mut self,
145	        ty: &TSType<'a>,
146	        name: &str,
147	        span_start: u32,
148	        span_end: u32,
149	        init_params: Option<&FormalParameters<'a>>,
150	    ) -> Option<ComponentMapping> {
151	        match ty {
152	            TSType::TSTypeReference(tr) => {
153	                let type_name = self.extract_type_ref_name(tr);
154	                let bare_name = type_name.strip_prefix("React.").unwrap_or(&type_name);
155	                if !FC_FAMILY_TYPE_NAMES.contains(&bare_name) {
156	                    return None;
157	                }
158	                let (props_name, type_args) = self.extract_props_arg(&tr.type_arguments)?;
159	                let (description, tags) = self.find_jsdoc_with_tags(span_start);
160	                Some(
161	                    ComponentMapping::new(
162	                        name.to_owned(),
163	                        props_name,
164	                        self.file_path.clone(),
165	                        span_start,
166	                        span_end,
167	                        DetectionRule::FcAnnotation,
168	                    )
169	                    .with_props_type_args(type_args)
170	                    .with_doc(description, tags)
171	                    .with_param_defaults(init_params.map(|p| self.extract_param_defaults(p)).unwrap_or_default()),
172	                )
173	            }
174	            TSType::TSParenthesizedType(p) => {
175	                self.extract_props_from_type_annotation(&p.type_annotation, name, span_start, span_end, init_params)
176	            }
177	            // `FC<DrawerProps> & { Panel: typeof Panel }`: the function-component member carries the props, the
178	            // other members are static properties attached to it.
179	            TSType::TSIntersectionType(members) => members.types.iter().find_map(|member| {
180	                self.extract_props_from_type_annotation(member, name, span_start, span_end, init_params)
181	            }),
182	            _ => None,
183	        }
184	    }
185	
186	    /// Try to detect: `const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(...)`
187	    pub(super) fn try_forward_ref<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
188	        let init = decl.init.as_ref()?;
189	        let call = match peel_expr(init) {
190	            Expression::CallExpression(ce) => ce,
191	            _ => return None,
192	        };
193	        if !self.is_forward_ref_call(call) {
194	            return None;
195	        }
196	
197	        // forwardRef<RefType, PropsType>(fn) — PropsType is the second type parameter
198	        let type_params = call.type_arguments.as_ref()?;
199	        if type_params.params.len() < 2 {
200	            return None;
201	        }
202	        let props_type = &type_params.params[1];
203	        let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
204	
205	        // The render function is forwardRef's call argument — its first parameter is
206	        // props (the second is `ref`, which never carries destructured defaults we care about).
207	        let render_params = match call.arguments.first() {
208	            Some(Argument::FunctionExpression(fe)) => Some(&fe.params),
209	            Some(Argument::ArrowFunctionExpression(afe)) => Some(&afe.params),
210	            _ => None,
211	        };
212	        let param_defaults = render_params.map(|p| self.extract_param_defaults(p)).unwrap_or_default();
213	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
214	
215	        Some(
216	            ComponentMapping::new(
217	                name.to_owned(),
218	                props_name,
219	                self.file_path.clone(),
220	                decl.span.start,
221	                decl.span.end,
222	                DetectionRule::ForwardRef,
223	            )
224	            .with_props_type_args(type_args)
225	            .with_doc(description, tags)
226	            .with_param_defaults(param_defaults),
227	        )
228	    }
229	
230	    /// Try to detect: `const Button = ({ variant }: ButtonProps) => ...` and the `function` expression form. The
231	    /// function must show it renders (see `evidence`): a typed first parameter alone also describes helpers such as
232	    /// `FormatName = (u: User) => string`. A first parameter that is not a named type is not a props object.
233	    pub(super) fn try_typed_function_expression<'a>(
234	        &mut self,
235	        decl: &Binding<'_, 'a>,
236	        name: &str,
237	    ) -> Option<ComponentMapping> {
238	        let (params, shape) = match peel_expr(decl.init.as_ref()?) {
239	            Expression::ArrowFunctionExpression(afe) => (&*afe.params, FunctionShape::of_arrow(afe)),
240	            Expression::FunctionExpression(fe) => (&*fe.params, FunctionShape::of_function(fe)),
241	            _ => return None,
242	        };
243	        let type_ann = params.items.first()?.type_annotation.as_ref()?;
244	        if let Err(reason) = renders(&shape, &*self) {
245	            self.decline_reason = Some(format!("'{name}' takes a typed props parameter but {reason}"));
246	            return None;
247	        }
248	        let (props_name, type_args) = self.extract_type_name_from_type(&type_ann.type_annotation)?;
249	        let param_defaults = self.extract_param_defaults(params);
250	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
251	        Some(
252	            ComponentMapping::new(
253	                name.to_owned(),
254	                props_name,
255	                self.file_path.clone(),
256	                decl.span.start,
257	                decl.span.end,
258	                DetectionRule::TypedFunctionExpression,
259	            )
260	            .with_props_type_args(type_args)
261	            .with_doc(description, tags)
262	            .with_param_defaults(param_defaults),
263	        )
264	    }
265	
266	    /// Try to detect: `const Button = anyHOC(function Button(props: ButtonProps) {...})`
267	    pub(super) fn try_hoc_wrapped<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
268	        let init = decl.init.as_ref()?;
269	        let call = match peel_expr(init) {
270	            Expression::CallExpression(ce) => ce,
271	            _ => return None,
272	        };
273	
274	        // First arg should be a function with a typed props param — or a forwardRef() call.
275	        let first_arg = call.arguments.first()?;
276	
277	        // `memo(forwardRef(…))`: the props come from forwardRef's type arguments, or from its render function.
278	        if let Argument::CallExpression(inner) = first_arg {
279	            if !self.is_forward_ref_call(inner) {
280	                return None;
281	            }
282	            // `forwardRef<Ref, Props>(…)` names the props in its second type argument; otherwise the render function's
283	            // first parameter does. A call with one type argument and no function (`forwardRef<Ref>()`) names neither.
284	            let props_type = inner.type_arguments.as_ref().and_then(|type_params| type_params.params.get(1));
285	            let Some(props_type) = props_type else {
286	                let render = inner.arguments.first()?;
287	                return self.mapping_from_typed_function(decl, name, call, render, DetectionRule::ForwardRef);
288	            };
289	            let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
290	            let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
291	            return Some(
292	                ComponentMapping::new(
293	                    name.to_owned(),
294	                    props_name,
295	                    self.file_path.clone(),
296	                    decl.span.start,
297	                    decl.span.end,
298	                    DetectionRule::ForwardRef,
299	                )
300	                .with_props_type_args(type_args)
301	                .with_doc(description, tags),
302	            );
303	        }
304	        let rule = if self.is_forward_ref_call(call) { DetectionRule::ForwardRef } else { DetectionRule::HocWrapper };
305	        self.mapping_from_typed_function(decl, name, call, first_arg, rule)
306	    }
307	
308	    /// The component a wrapper call builds from a render function whose first parameter names the props type:
309	    /// `memo(function Button(props: ButtonProps) {…})`, and the same inside `memo(forwardRef(…))`. `call` is the outermost
310	    /// wrapper call, whose type arguments may add props (`wrapper.rs`).
311	    fn mapping_from_typed_function<'a>(
312	        &mut self,
313	        decl: &Binding<'_, 'a>,
314	        name: &str,
315	        call: &CallExpression<'a>,
316	        function: &Argument<'a>,
317	        rule: DetectionRule,
318	    ) -> Option<ComponentMapping> {
319	        let (fn_name, params, shape) = match function {
320	            Argument::FunctionExpression(fe) => {
321	                (fe.id.as_ref().map(|id| id.name.as_str()), &fe.params, FunctionShape::of_function(fe))
322	            }
323	            Argument::ArrowFunctionExpression(afe) => (None, &afe.params, FunctionShape::of_arrow(afe)),
324	            _ => return None,
325	        };
326	
327	        // Rules out anonymous utility functions, which aren't components.
328	        if let Some(fn_name_str) = fn_name {
329	            if !is_pascal_case(fn_name_str) {
330	                return None;
331	            }
332	        }
333	
334	        let first_param = params.items.first()?;
335	        let type_ann = first_param.type_annotation.as_ref()?;
336	        // `debounce((q: Row) => …)` and `createSelector((s: State) => …)` have the same shape as `memo(…)`.
337	        if let Err(reason) = renders(&shape, &*self) {
338	            self.decline_reason = Some(format!("'{name}' wraps a typed function that {reason}"));
339	            return None;
340	        }
341	        let (props_name, type_args) = self.extract_type_name_from_type(&type_ann.type_annotation)?;
342	
343	        let param_defaults = self.extract_param_defaults(params);
344	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
345	
346	        let mapping = ComponentMapping::new(
347	            name.to_owned(),
348	            props_name,
349	            self.file_path.clone(),
350	            decl.span.start,
351	            decl.span.end,
352	            rule,
353	        )
354	        .with_props_type_args(type_args)
355	        .with_doc(description, tags)
356	        .with_param_defaults(param_defaults);
357	        // `factory<Payload>((props: P) => …)`: a generic wrapper's result type can add props, as in `wrapper.rs`.
358	        Some(match self.wrapper_callee(call) {
359	            Some(callee) => mapping.with_wrapper_callee(callee),
360	            None => mapping,
361	        })
362	    }
363	
364	    /// Try to detect declared `ForwardRefExoticComponent<Props>` and `MemoExoticComponent<(props: Props) => JSX>` values.
365	    ///
366	    /// Common in .d.ts files — no initializer, just a type annotation.
367	    pub(super) fn try_exotic_component_decl<'a>(
368	        &mut self,
369	        decl: &VariableDeclarator<'a>,
370	        name: &str,
371	    ) -> Option<ComponentMapping> {
372	        let type_ann = decl.type_annotation.as_ref()?;
373	        let ct = self.ts_type_to_collected(&type_ann.type_annotation);
374	
375	        let is_react_type = |name: &str, expected: &str| {
376	            name == expected
377	                || name.rsplit_once('.').is_some_and(|(prefix, suffix)| {
378	                    suffix == expected
379	                        && (prefix == "React"
380	                            || self.data.imports.iter().any(|binding| {
381	                                binding.local_name == prefix
382	                                    && binding.exported_name == "*"
383	                                    && binding.specifier == "react"
384	                            }))
385	                })
386	        };
387	        let exotic_args = |ty: &crate::types::CollectedType| match ty {
388	            crate::types::CollectedType::Named { name, args } if is_react_type(name, "ForwardRefExoticComponent") => {
389	                Some((args.clone(), false))
390	            }
391	            crate::types::CollectedType::Named { name, args } if is_react_type(name, "MemoExoticComponent") => {
392	                Some((args.clone(), true))
393	            }
394	            _ => None,
395	        };
396	        let (args, memoized) = match &ct {
397	            crate::types::CollectedType::Intersection(members) => members.iter().find_map(exotic_args),
398	            other => exotic_args(other),
399	        }?;
400	
401	        let first_arg = args.first()?;
402	
403	        // RefAttributes is metadata on the value, not a prop base. Keep every other member: declaration generators
404	        // often write several props objects into one ForwardRefExoticComponent argument.
405	        let props_type = match first_arg {
406	            crate::types::CollectedType::Function { params, .. } if memoized => params.first()?.clone(),
407	            _ if memoized => return None,
408	            crate::types::CollectedType::Intersection(members) => {
409	                let mut props: Vec<_> = members
410	                    .iter()
411	                    .filter(|member| {
412	                        !matches!(member, crate::types::CollectedType::Named { name, .. }
413	                            if is_react_type(name, "RefAttributes"))
414	                    })
415	                    .cloned()
416	                    .collect();
417	                match props.len() {
418	                    0 => return None,
419	                    1 => props.remove(0),
420	                    _ => crate::types::CollectedType::Intersection(props),
421	                }
422	            }
423	            other => other.clone(),
424	        };
425	
426	        let (props_name, props_args) = match props_type {
427	            crate::types::CollectedType::Named { name, args } => (name, args),
428	            props => {
429	                let name = format!("__anon_{}", self.data.type_aliases.len());
430	                let key = self.scoped_key(&name);
431	                self.data.type_aliases.insert(
432	                    key,
433	                    crate::types::CollectedTypeAlias::Passthrough { target: props, file_path: self.file_path.clone() },
434	                );
435	                (name.into(), vec![])
436	            }
437	        };
438	
439	        Some(
440	            ComponentMapping::new(
441	                name.to_owned(),
442	                props_name,
443	                self.file_path.clone(),
444	                decl.span.start,
445	                decl.span.end,
446	                if memoized { DetectionRule::MemoExoticDecl } else { DetectionRule::ForwardRefExoticDecl },
447	            )
448	            .with_props_type_args(props_args)
449	            .with_doc(self.find_jsdoc(decl.span.start), BTreeMap::new())
450	            .with_param_defaults(rustc_hash::FxHashMap::default()),
451	        )
452	    }
453	
454	    /// A dependency can publish a component as `declare const Tab: (props: TabProps) => ReactElement | null`.
455	    pub(super) fn try_declared_callable_component<'a>(
456	        &mut self,
457	        decl: &VariableDeclarator<'a>,
458	        name: &str,
459	    ) -> Option<ComponentMapping> {
460	        let annotation = &decl.type_annotation.as_ref()?.type_annotation;
461	        let (params, return_type, type_parameters) = if let TSType::TSFunctionType(function) = annotation {
462	            (function.params.as_ref(), function.return_type.as_ref(), function.type_parameters.as_deref())
463	        } else if let TSType::TSTypeLiteral(literal) = annotation {
464	            let mut calls = literal.members.iter().filter_map(|member| match member {
465	                TSSignature::TSCallSignatureDeclaration(call) => Some(call.as_ref()),
466	                TSSignature::TSIndexSignature(_)
467	                | TSSignature::TSPropertySignature(_)
468	                | TSSignature::TSConstructSignatureDeclaration(_)
469	                | TSSignature::TSMethodSignature(_) => None,
470	            });
471	            let call = calls.next()?;
472	            if calls.next().is_some() {
473	                return None;
474	            }
475	            (call.params.as_ref(), call.return_type.as_deref()?, call.type_parameters.as_deref())
476	        } else {
477	            return None;
478	        };
479	        let [parameter] = params.items.as_slice() else { return None };
480	        let return_type = self.ts_type_to_collected(&return_type.type_annotation);
481	        let is_element = |name: &str| {
482	            matches!(name, "React.ReactElement" | "React.JSX.Element" | "JSX.Element")
483	                || name.strip_suffix(".JSX.Element").is_some_and(|namespace| {
484	                    self.data.imports.iter().any(|binding| {
485	                        binding.local_name == namespace
486	                            && binding.exported_name == "*"
487	                            && matches!(binding.specifier.as_str(), "react/jsx-runtime" | "react/jsx-dev-runtime")
488	                    })
489	                })
490	                || self.data.imports.iter().any(|binding| {
491	                    binding.local_name == name
492	                        && binding.exported_name == "ReactElement"
493	                        && binding.specifier == "react"
494	                })
495	        };
496	        let returns_element = |ty: &crate::types::CollectedType| match ty {
497	            crate::types::CollectedType::Named { name, .. } => is_element(name),
498	            crate::types::CollectedType::Union(members) => members.iter().any(|member| {
499	                if let crate::types::CollectedType::Named { name, .. } = member {
500	                    is_element(name)
501	                } else {
502	                    false
503	                }
504	            }),
505	            _ => false,
506	        };
507	        if !returns_element(&return_type) {
508	            return None;
509	        }
510	        let (props_name, mut props_args) =
511	            self.extract_type_name_from_type(&parameter.type_annotation.as_ref()?.type_annotation)?;
512	        let type_params: Vec<crate::types::TypeName> = type_parameters
513	            .map(|declaration| declaration.params.iter().map(|param| param.name.name.as_str().into()).collect())
514	            .unwrap_or_default();
515	        if props_name.starts_with("__anon_") && !type_params.is_empty() {
516	            self.data.type_alias_params.insert(self.scoped_key(&props_name), type_params.clone());
517	            props_args = type_params
518	                .iter()
519	                .map(|name| crate::types::CollectedType::Named { name: name.clone(), args: Vec::new() })
520	                .collect();
521	        }
522	        let mut mapping = ComponentMapping::new(
523	            name.to_owned(),
524	            props_name,
525	            self.file_path.clone(),
526	            decl.span.start,
527	            decl.span.end,
528	            DetectionRule::FunctionDeclaration,
529	        )
530	        .with_props_type_args(props_args)
531	        .with_doc(self.find_jsdoc(decl.span.start), BTreeMap::new());
532	        mapping.type_params = type_params;
533	        Some(mapping)
534	    }
