1	//! `impl Visit for SourceDataCollector` — the AST walker entry points.
2	
3	use oxc_ast::ast::*;
4	use oxc_ast_visit::{walk, Visit};
5	use oxc_syntax::scope::ScopeFlags;
6	
7	use crate::types::{
8	    CollectedInterface, ComponentMapping, DetectionRule, DiagnosticCode, EnumEntry, EnumValue, ExtendsRef,
9	    ImportBinding, LexedExport, RawProp, TypeName,
10	};
11	
12	use super::component::Binding;
13	use super::{declaration_name, is_pascal_case, js_text, SourceDataCollector};
14	
15	impl<'a, 'src> Visit<'a> for SourceDataCollector<'src> {
16	    fn visit_import_declaration(&mut self, node: &ImportDeclaration<'a>) {
17	        let specifier = js_text::lossy(node.source.value).into_owned();
18	        let is_type_only = node.import_kind.is_type();
19	
20	        if let Some(specifiers) = &node.specifiers {
21	            for spec in specifiers {
22	                match spec {
23	                    ImportDeclarationSpecifier::ImportSpecifier(s) => {
24	                        let local = s.local.name.as_str();
25	                        let imported = s.imported.name();
26	                        let imported_str = imported.as_str();
27	                        self.imported_names.insert(local.into());
28	                        self.data.imports.push(ImportBinding {
29	                            local_name: local.into(),
30	                            exported_name: imported_str.into(),
31	                            specifier: specifier.clone(),
32	                            is_type_only: is_type_only || s.import_kind.is_type(),
33	                        });
34	                    }
35	                    ImportDeclarationSpecifier::ImportDefaultSpecifier(s) => {
36	                        let local = s.local.name.as_str();
37	                        self.imported_names.insert(local.into());
38	                        self.data.imports.push(ImportBinding {
39	                            local_name: local.into(),
40	                            exported_name: "default".into(),
41	                            specifier: specifier.clone(),
42	                            is_type_only,
43	                        });
44	                    }
45	                    ImportDeclarationSpecifier::ImportNamespaceSpecifier(s) => {
46	                        let local = s.local.name.as_str();
47	                        self.imported_names.insert(local.into());
48	                        self.data.imports.push(ImportBinding {
49	                            local_name: local.into(),
50	                            exported_name: "*".into(),
51	                            specifier: specifier.clone(),
52	                            is_type_only,
53	                        });
54	                    }
55	                }
56	            }
57	        }
58	
59	        // Don't walk children — we've handled everything
60	    }
61	
62	    /// `export { Foo }`: local specifiers, no source.
63	    fn visit_export_named_declaration(&mut self, node: &ExportNamedDeclaration<'a>) {
64	        for spec in &node.specifiers {
65	            self.record_exported_local(spec.local.name().as_str());
66	            // Recorded as a local declaration for now; `finish()` turns it into a re-export when `local` is an import.
67	            let (local, exported) = (spec.local.name().as_str(), spec.exported.name().as_str());
68	            self.pending_local_exports.push((self.data.exports.len(), local.to_owned()));
69	            self.data.exports.push(LexedExport::LocalDeclaration {
70	                name: exported.to_owned(),
71	                is_type_only: node.export_kind.is_type() || spec.export_kind.is_type(),
72	                declared_as: (local != exported).then(|| local.to_owned()),
73	            });
74	            if let Some((base_name, props_name)) = self.cast_component_aliases.get(local).cloned() {
75	                if let Some(index) =
76	                    self.data.component_mappings.iter().position(|mapping| mapping.component_name == base_name)
77	                {
78	                    let mut public = self.data.component_mappings[index].clone();
79	                    public.component_name = exported.to_owned();
80	                    public.props_type_name = props_name;
81	                    public.props_type_args.clear();
82	                    public.wrapper_callee = None;
83	                    public.rule = crate::types::DetectionRule::FcAnnotation;
84	                    if base_name == exported {
85	                        self.data.component_mappings[index] = public;
86	                    } else {
87	                        self.data.component_mappings.push(public);
88	                    }
89	                    self.record_exported_local(exported);
90	                }
91	            }
92	        }
93	
94	        walk::walk_export_named_declaration(self, node);
95	    }
96	
97	    /// `export { X } from "./y"`.
98	    fn visit_export_from_declaration(&mut self, node: &ExportFromDeclaration<'a>) {
99	        let src = js_text::lossy(node.source.value).into_owned();
100	        for spec in &node.specifiers {
101	            self.data.exports.push(LexedExport::ReExportNamed {
102	                // local_name is what we call it here; source_name is the original
103	                local_name: spec.exported.name().as_str().to_owned(),
104	                source_name: spec.local.name().as_str().to_owned(),
105	                source_specifier: src.clone(),
106	                is_type_only: node.export_kind.is_type() || spec.export_kind.is_type(),
107	            });
108	        }
109	
110	        walk::walk_export_from_declaration(self, node);
111	    }
112	
113	    /// `export interface Foo` / `export const X`. `is_type_only` is always false: `export_kind` only marks
114	    /// `export type { A }`, and `export enum` declares a runtime value.
115	    fn visit_export_declaration(&mut self, node: &ExportDeclaration<'a>) {
116	        if let Some(name) = declaration_name(&node.declaration) {
117	            self.data.exports.push(LexedExport::LocalDeclaration {
118	                name: name.to_owned(),
119	                is_type_only: false,
120	                declared_as: None,
121	            });
122	        }
123	        // `export const A = …, B = …` exports every declarator.
124	        match &node.declaration {
125	            Declaration::VariableDeclaration(vd) => {
126	                for declarator in &vd.declarations {
127	                    if let BindingPattern::BindingIdentifier(id) = &declarator.id {
128	                        self.record_exported_local(id.name.as_str());
129	                    }
130	                }
131	            }
132	            declaration => {
133	                if let Some(name) = declaration_name(declaration) {
134	                    self.record_exported_local(name);
135	                }
136	            }
137	        }
138	
139	        // Walk the declaration so sub-visitors (interface, type alias, etc.) fire
140	        walk::walk_export_declaration(self, node);
141	    }
142	
143	    fn visit_export_all_declaration(&mut self, node: &ExportAllDeclaration<'a>) {
144	        let src = js_text::lossy(node.source.value).into_owned();
145	        if let Some(ns) = &node.exported {
146	            // `export * as Ns from "./y"`
147	            self.data.exports.push(LexedExport::ReExportNamespace {
148	                namespace: ns.name().as_str().to_owned(),
149	                source_specifier: src,
150	            });
151	        } else {
152	            // `export * from "./y"`
153	            self.data
154	                .exports
155	                .push(LexedExport::ReExportAll { source_specifier: src, is_type_only: node.export_kind.is_type() });
156	        }
157	    }
