201	    fn visit_ts_type_alias_declaration(&mut self, node: &TSTypeAliasDeclaration<'a>) {
202	        let name = node.id.name.as_str();
203	        let key = self.scoped_key(name);
204	
205	        let Some(alias) = self.classify_type_alias(name, &node.type_annotation) else {
206	            return;
207	        };
208	        self.data.type_aliases.insert(key.clone(), alias);
209	
210	        // Record declared type parameter names (`type Assign<T, U> = ...` → ["T", "U"])
211	        // so the resolver can substitute call-site arguments into the alias body —
212	        // see `resolver/substitute.rs`. Absent entry = non-generic alias.
213	        if let Some(type_parameters) = &node.type_parameters {
214	            let params: Vec<TypeName> = type_parameters.params.iter().map(|p| p.name.name.as_str().into()).collect();
215	            if !params.is_empty() {
216	                self.record_type_param_defaults(&key, &type_parameters.params);
217	                self.data.type_alias_params.insert(key, params);
218	            }
219	        }
220	    }
