468	    fn visit_class(&mut self, class: &Class<'a>) {
469	        // `class Button extends React.Component<Props> { ... }` — shared entry
470	        // point for both a ClassDeclaration and a self-named ClassExpression;
471	        // an anonymous ClassExpression (no `class.id`) is instead picked up by
472	        // `try_class_expression_wrapped` in `visit_variable_declaration`'s
473	        // detector chain, from the outer binding's name.
474	        if let Some(id) = &class.id {
475	            let params = class
476	                .type_parameters
477	                .as_ref()
478	                .map(|declaration| declaration.params.iter().map(|p| p.name.name.as_str().into()).collect())
479	                .unwrap_or_default();
480	            self.pending_classes.push((self.scoped_key(id.name.as_str()), id.name.as_str().into(), params));
481	        }
482	        if self.is_tsx && self.function_depth > 0 {
483	            if let Some(id) = &class.id {
484	                let name = id.name.as_str();
485	                if is_pascal_case(name) && self.super_class_is_component_family(class).is_some() {
486	                    self.skip_local_component(name, class.span);
487	                }
488	            }
489	        } else if self.is_tsx {
490	            if let Some(id) = &class.id {
491	                let name = id.name.as_str();
492	                if is_pascal_case(name) {
493	                    if let Some(family) = self.super_class_is_component_family(class) {
494	                        if let Some(mapping) = self.try_class_component(class, name) {
495	                            self.data.component_mappings.push(mapping);
496	                        } else if class.heritage.as_ref().is_some_and(|h| h.type_arguments.is_some()) {
497	                            // Extends Component/PureComponent WITH type args, but the
498	                            // props argument itself is an exotic shape
499	                            // extract_type_name_from_type doesn't match. No type args
500	                            // at all is left silent — mirrors visit_function's Pattern 4
501	                            // zero-params contract (a genuinely untyped candidate, not a
502	                            // malformed one).
503	                            self.record_skip(
504	                                DiagnosticCode::SkippedCandidate,
505	                                format!(
506	                                    "'{name}' is a class component extending {family} whose props type \
507	                                     argument isn't a recognizable props type reference"
508	                                ),
509	                                class.span,
510	                            );
511	                        }
512	                    }
513	                }
514	            }
515	        }
516	        walk::walk_class(self, class);
517	    }
