595	    fn visit_expression_statement(&mut self, node: &ExpressionStatement<'a>) {
596	        self.try_scan_display_name(node);
597	        self.try_scan_default_props(node);
598	        self.record_member_assignment(node);
599	        if self.is_tsx {
