139	    /// Record `const Name = callee<...>(first, ...)` as a candidate. Returns whether it was recorded.
140	    pub(super) fn try_record_wrapper_call<'a>(&mut self, decl: &super::component::Binding<'_, 'a>, name: &str) -> bool {
141	        let Some(init) = decl.init else { return false };
142	        let Expression::CallExpression(call) = super::component::peel_expr(init) else { return false };
143	        let Some(type_arguments) = call.type_arguments.as_ref() else { return false };
144	        let Some(callee) = self.extract_callee_name(call) else { return false };
145	        let creates_context = self.react_api(&call.callee) == Some(super::ReactApi::CreateContext);
146	        let needs_payload = match component_argument_evidence(creates_context, call, &*self) {
147	            Ok(ArgumentEvidence::Sufficient) => false,
148	            Ok(ArgumentEvidence::TagNeedsPayload) => true,
149	            Err(reason) => {
150	                self.decline_reason = Some(format!("'{name}' is a generic call to '{callee}' that {reason}"));
151	                return false;
152	            }
153	        };
154	        let type_args: Vec<WrapperTypeArg> = type_arguments
155	            .params
156	            .iter()
157	            .map(|ty| WrapperTypeArg { reference: self.extract_type_name_from_type(ty) })
158	            .collect();
159	        let Some(callee) = self.wrapper_callee(call) else { return false };
160	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
161	        self.pending_wrappers.push(PendingWrapper {
162	            name: name.to_owned(),
163	            needs_payload,
164	            tag: None,
165	            type_args,
166	            callee: Some(callee),
167	            rule: DetectionRule::WrapperTypeArgument,
168	            description,
169	            tags,
170	            span: decl.span,
171	        });
172	        true
173	    }
