175	    /// Record `const Center = chakra("div", { ... })` as a candidate: a call given an intrinsic tag name and a config
176	    /// object, whose props type is the one declared in this file for that tag (`interface CenterProps extends
177	    /// HTMLChakraProps<"div">`). Nothing here names a library; calls that build elements rather than components
178	    /// (`createElement("div", { ... })`) are excluded by name, as React's own API.
179	    pub(super) fn try_record_tagged_factory<'a>(
180	        &mut self,
181	        decl: &super::component::Binding<'_, 'a>,
182	        name: &str,
183	    ) -> bool {
184	        let Some(init) = decl.init else { return false };
185	        let Expression::CallExpression(call) = super::component::peel_expr(init) else { return false };
186	        if call.type_arguments.is_some() {
187	            return false;
188	        }
189	        let [tag, config] = call.arguments.as_slice() else { return false };
190	        let Some(Expression::StringLiteral(tag)) = tag.as_expression().map(super::component::peel_expr) else {
191	            return false;
192	        };
193	        let tag_name = tag.value.as_str().map(str::to_owned);
194	        let is_tag = tag.value.as_str().is_some_and(|name| {
195	            name.starts_with(|c: char| c.is_ascii_lowercase())
196	                && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
197	        });
198	        let has_config =
199	            matches!(config.as_expression().map(super::component::peel_expr), Some(Expression::ObjectExpression(_)));
200	        let Some(callee) = self.extract_callee_name(call) else { return false };
201	        let element_builder = matches!(
202	            callee.rsplit('.').next(),
203	            Some("createElement" | "cloneElement" | "jsx" | "jsxs" | "jsxDEV" | "h")
204	        );
205	        if !is_tag || !has_config || element_builder {
206	            return false;
207	        }
208	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
209	        self.pending_wrappers.push(PendingWrapper {
210	            name: name.to_owned(),
211	            needs_payload: false,
212	            tag: tag_name,
213	            type_args: Vec::new(),
214	            callee: None,
215	            rule: DetectionRule::TaggedFactory,
216	            description,
217	            tags,
218	            span: decl.span,
219	        });
220	        true
221	    }
