223	    /// Whether a generic call names the props type of the component it builds in its type arguments, as in
224	    /// `withContext<HTMLDivElement, OverlayProps>(BaseOverlay, …)`. The call's own props then replace those of the
225	    /// component it receives.
226	    pub(super) fn call_names_props_type<'a>(&mut self, call: &CallExpression<'a>) -> bool {
227	        let Some(type_arguments) = call.type_arguments.as_ref() else { return false };
228	        let type_args: Vec<WrapperTypeArg> = type_arguments
229	            .params
230	            .iter()
231	            .map(|ty| WrapperTypeArg { reference: self.extract_type_name_from_type(ty) })
232	            .collect();
233	        matches!(self.select_wrapper_props(&type_args), PropsSelection::Found { from_payload: false, .. })
234	    }
