236	    /// Turn the recorded candidates into mappings, now that every declaration in the file is known.
237	    pub(super) fn promote_wrapper_calls(&mut self) {
238	        let pending_wrappers = std::mem::take(&mut self.pending_wrappers);
239	        let tag_uses =
240	            |tag: &str| pending_wrappers.iter().filter(|pending| pending.tag.as_deref() == Some(tag)).count();
241	        let shared_tags: Vec<bool> = pending_wrappers
242	            .iter()
243	            .map(|pending| pending.tag.as_deref().is_some_and(|tag| tag_uses(tag) > 1))
244	            .collect();
245	        // A tagged factory takes the props type no other component in the file takes, so every other candidate is
246	        // promoted first, in source order: `StyledGroup = chakra("div", …)` comes before `Group = withContext<…,
247	        // GroupProps>(StyledGroup)` and would otherwise take `GroupProps` before `Group` claims it.
248	        let (tagged, others): (Vec<_>, Vec<_>) =
249	            pending_wrappers.into_iter().zip(shared_tags).partition(|(pending, _)| pending.tag.is_some());
250	        for (pending, shared_tag) in others.into_iter().chain(tagged) {
251	            if self.data.component_mappings.iter().any(|m| m.component_name == pending.name) {
252	                continue;
253	            }
254	            if let Some(tag) = &pending.tag {
255	                let Some((props_name, props_args)) = self.tagged_factory_props(&pending.name, tag, shared_tag) else {
256	                    self.record_skip(
257	                        DiagnosticCode::SkippedCandidate,
258	                        format!(
259	                            "'{}' is built from a tag and a config object, but no props type declared in this file gives the tag \"{tag}\"",
260	                            pending.name
261	                        ),
262	                        pending.span,
263	                    );
264	                    continue;
265	                };
266	                self.data.component_mappings.push(
267	                    ComponentMapping::new(
268	                        pending.name,
269	                        props_name,
270	                        self.file_path.clone(),
271	                        pending.span.start,
272	                        pending.span.end,
273	                        pending.rule,
274	                    )
275	                    .with_props_type_args(props_args)
276	                    .with_doc(pending.description, pending.tags),
277	                );
278	                continue;
279	            }
280	            let selected = match self.select_wrapper_props(&pending.type_args) {
281	                PropsSelection::Found { name, args, from_payload } if from_payload || !pending.needs_payload => {
282	                    Some((name, args))
283	                }
284	                PropsSelection::UnusablePayload { alias } => {
285	                    self.record_skip(
286	                        DiagnosticCode::SkippedCandidate,
287	                        format!(
288	                            "'{}' is built from the factory payload '{alias}', whose `props` member is not a named type",
289	                            pending.name
290	                        ),
291	                        pending.span,
292	                    );
293	                    continue;
294	                }
295	                PropsSelection::Found { .. } | PropsSelection::None => None,
296	            };
297	            let Some((props_name, props_args)) = selected else {
298	                self.record_skip(
299	                    DiagnosticCode::SkippedCandidate,
300	                    format!(
301	                        "'{}' looks like a component built by a wrapper call, but none of its type arguments names {}",
302	                        pending.name,
303	                        if pending.needs_payload {
304	                            "a factory payload, which a tag-name argument needs"
305	                        } else {
306	                            "a props type declared in this file or ending in Props"
307	                        }
308	                    ),
309	                    pending.span,
310	                );
311	                continue;
312	            };
313	            let mut mapping = ComponentMapping::new(
314	                pending.name,
315	                props_name,
316	                self.file_path.clone(),
317	                pending.span.start,
318	                pending.span.end,
319	                pending.rule,
320	            )
321	            .with_props_type_args(props_args)
322	            .with_doc(pending.description, pending.tags);
323	            if let Some(callee) = pending.callee {
324	                mapping = mapping.with_wrapper_callee(callee);
325	            }
326	            self.data.component_mappings.push(mapping);
327	        }
328	    }
