366	    /// The callee of a generic call that builds a component, and its type arguments, for the props its result type
367	    /// adds (`resolver::callee`). `None` for a call without type arguments.
368	    pub(super) fn wrapper_callee<'a>(&mut self, call: &CallExpression<'a>) -> Option<WrapperCallee> {
369	        let type_arguments = call.type_arguments.as_ref()?;
370	        let name = self.extract_callee_name(call)?;
371	        Some(WrapperCallee {
372	            name: name.as_str().into(),
373	            type_args: type_arguments.params.iter().map(|ty| self.ts_type_to_collected(ty)).collect(),
374	        })
375	    }
