377	    /// Record a generic function's annotated, asserted, or single returned local factory result. A wrapper call to
378	    /// it then gets the props that result adds (`resolver::callee`).
379	    pub(super) fn record_function_result<'a>(&mut self, func: &Function<'a>) {
380	        let (Some(id), Some(type_parameters)) = (&func.id, func.type_parameters.as_deref()) else { return };
381	        let (result, returned_call) = match &func.return_type {
382	            Some(annotation) => (self.ts_type_to_collected(&annotation.type_annotation), None),
383	            None => match asserted_return_type(func) {
384	                Some(ty) => (self.ts_type_to_collected(ty), None),
385	                None => (CollectedType::Unknown, returned_local_call(self, func)),
386	            },
387	        };
388	        if matches!(result, CollectedType::Unknown) && returned_call.is_none() {
389	            return;
390	        }
391	        let type_params = super::type_param_names(Some(type_parameters));
392	        let key = self.scoped_key(id.name.as_str());
393	        self.data.function_results.insert(key, FunctionResult { type_params, result, returned_call });
394	    }
