396	    /// Pick the props type from a wrapper call's type arguments, last first (the props usually follow the element).
397	    fn select_wrapper_props(&self, type_args: &[WrapperTypeArg]) -> PropsSelection {
398	        for arg in type_args.iter().rev() {
399	            let Some((name, args)) = &arg.reference else { continue };
400	            if is_element_type(name) {
401	                continue;
402	            }
403	            // A factory payload is never itself the props type, even though it is declared in this file.
404	            match self.payload_props(name) {
405	                Some(Some((props, props_args))) => {
406	                    return PropsSelection::Found { name: props, args: props_args, from_payload: true };
407	                }
408	                Some(None) => return PropsSelection::UnusablePayload { alias: name.clone() },
409	                None => {}
410	            }
411	            let declared_here = self.data.interfaces.contains_key(&self.scoped_key(name))
412	                || self.data.type_aliases.contains_key(&self.scoped_key(name));
413	            // A name from another file cannot be inspected here; only the props naming convention vouches for it.
414	            if declared_here || name.ends_with("Props") {
415	                return PropsSelection::Found { name: name.clone(), args: args.clone(), from_payload: false };
416	            }
417	        }
418	        PropsSelection::None
419	    }
420	
421	    /// For an alias that is a factory payload (`type ButtonFactory = Anything<{ props: ButtonProps; ... }>`), the
422	    /// props type and its arguments (`ButtonProps`, or `OverflowListProps` with `[any]`), or `None` when the `props`
423	    /// member is not a named type. `None` outright when the alias is not a payload.
424	    fn payload_props(&self, alias_name: &str) -> Option<Option<(TypeName, Vec<CollectedType>)>> {
425	        let CollectedTypeAlias::Passthrough { target: CollectedType::Named { args, .. }, .. } =
426	            self.data.type_aliases.get(&self.scoped_key(alias_name))?
427	        else {
428	            return None;
429	        };
430	        let props_member = args.iter().find_map(|arg| match arg {
431	            CollectedType::Object(fields) => fields.iter().find(|field| field.name == PAYLOAD_PROPS_MEMBER),
432	            _ => None,
433	        })?;
434	        Some(match &props_member.collected_type {
435	            CollectedType::Named { name, args } => Some((name.clone(), args.clone())),
436	            _ => None,
437	        })
438	    }
439	}
