515	/// Where a wrapper call's props come from.
516	enum PropsSelection {
517	    Found {
518	        name: TypeName,
519	        args: Vec<CollectedType>,
520	        from_payload: bool,
521	    },
522	    /// A factory payload whose `props` member names no type, so neither it nor the payload can be the props type.
523	    UnusablePayload {
524	        alias: TypeName,
525	    },
526	    None,
527	}
