1	//! Components declared through a wrapper call whose props travel as a type argument:
2	//! `const Button = polymorphicFactory<ButtonFactory>(...)`, `const Item = withContext<HTMLDivElement, ItemProps>(...)`.
3	//!
4	//! Nothing here names a library. A candidate is a PascalCase binding initialized with a generic call whose first
5	//! argument could plausibly be a component (a function, a tag name, another component). The props type is chosen from
6	//! the type arguments by shape, and only against declarations visible in the same file, so the rule needs no
7	//! cross-file state. Candidates are resolved when the file finishes, because `type ButtonFactory = ...` is often
8	//! declared after the call that uses it.
9	
10	use std::collections::BTreeMap;
11	
12	use oxc_ast::ast::*;
13	use oxc_span::Span;
14	
15	use crate::types::{
16	    CollectedType, CollectedTypeAlias, ComponentMapping, DetectionRule, DiagnosticCode, ExtendsRef, FunctionResult,
17	    TypeName, WrapperCallee,
18	};
19	
20	use super::evidence::{renders, FunctionShape, ReactBinding};
21	use super::SourceDataCollector;
22	
23	/// One type argument of a candidate wrapper call.
24	pub(crate) struct WrapperTypeArg {
25	    /// The reference name and its stringified type arguments, when the argument is a plain type reference.
26	    reference: Option<(TypeName, Vec<CollectedType>)>,
27	}
28	
29	/// A wrapper call waiting for the rest of the file to be seen.
30	pub(crate) struct PendingWrapper {
31	    name: String,
32	    /// The only evidence was a tag name, so the props must come from a factory payload.
33	    needs_payload: bool,
34	    /// The intrinsic tag of a tagged factory (`"div"` in `chakra("div", { … })`), whose props type is then the
35	    /// declaration in this file that gives that tag.
36	    tag: Option<String>,
37	    type_args: Vec<WrapperTypeArg>,
38	    callee: Option<WrapperCallee>,
39	    rule: DetectionRule,
40	    description: String,
41	    tags: BTreeMap<String, String>,
42	    span: Span,
43	}
44	
45	/// Member that carries the props type inside a factory payload: `Factory<{ props: ButtonProps; ... }>`.
46	const PAYLOAD_PROPS_MEMBER: &str = "props";
47	
48	/// Names that are DOM elements or refs rather than props, so they are never the props argument.
49	fn is_element_type(name: &str) -> bool {
50	    let bare = name.rsplit('.').next().unwrap_or(name);
51	    bare == "Element" || ((bare.starts_with("HTML") || bare.starts_with("SVG")) && bare.ends_with("Element"))
52	}
53	
54	fn is_element_type_arg(ty: &TSType<'_>) -> bool {
55	    match ty {
56	        TSType::TSTypeReference(r) => match &r.type_name {
57	            TSTypeName::IdentifierReference(id) => is_element_type(id.name.as_str()),
58	            TSTypeName::QualifiedName(q) => is_element_type(q.right.name.as_str()),
59	            _ => false,
60	        },
61	        _ => false,
62	    }
63	}
64	
65	fn is_component_reference(name: &str) -> bool {
66	    // `_Box` is Mantine's spelling of an implementation component.
67	    name.trim_start_matches(['_', '$']).starts_with(|c: char| c.is_ascii_uppercase())
68	}
69	
70	/// How strongly the first argument says the call builds a component.
71	enum ArgumentEvidence {
72	    Sufficient,
73	    /// A tag name with no element type argument: a component only if a type argument is a factory payload.
74	    TagNeedsPayload,
75	}
76	
77	/// Evidence that the call builds a component from its first argument: a function that renders (Mantine's
78	/// `factory<F>((props) => <Box />)`), a tag name next to an element type argument (`withContext<HTMLDivElement, P>("div")`)
79	/// or a factory payload (`tableElement<TableTrFactory>("tr")`), a reference to a component
80	/// (`withRootProvider<P>(Ark.Root)`), or a wrapped component (`polymorphic<P>(forwardRef(...))`). A tag string alone
81	/// also describes `makeLabel<P>("button")`, and a lowercase value describes a context default or a store, so neither
82	/// counts.
83	fn component_argument_evidence(
84	    creates_context: bool,
85	    call: &CallExpression<'_>,
86	    react: ReactBinding<'_>,
87	) -> Result<ArgumentEvidence, &'static str> {
88	    if creates_context {
89	        return Err("creates a context");
90	    }
91	    let Some(first) = call.arguments.first().and_then(Argument::as_expression).map(super::component::peel_expr) else {
92	        return Err("has no argument that could be a component");
93	    };
94	    let element_type_arg = || call.type_arguments.as_ref().is_some_and(|a| a.params.iter().any(is_element_type_arg));
95	    let sufficient = |r: Result<(), &'static str>| r.map(|()| ArgumentEvidence::Sufficient);
96	    match first {
97	        Expression::ArrowFunctionExpression(f) => sufficient(
98	            renders(&FunctionShape::of_arrow(f), react).map_err(|_why| "is given a function that never renders"),
99	        ),
100	        Expression::FunctionExpression(f) => sufficient(
101	            renders(&FunctionShape::of_function(f), react).map_err(|_why| "is given a function that never renders"),
102	        ),
103	        Expression::StringLiteral(_) if element_type_arg() => Ok(ArgumentEvidence::Sufficient),
104	        Expression::StringLiteral(_) => Ok(ArgumentEvidence::TagNeedsPayload),
105	        Expression::Identifier(id) if is_component_reference(id.name.as_str()) => Ok(ArgumentEvidence::Sufficient),
106	        Expression::StaticMemberExpression(m) if is_component_reference(m.property.name.as_str()) => {
107	            Ok(ArgumentEvidence::Sufficient)
108	        }
109	        Expression::CallExpression(inner)
110	            if react.is_react_wrapper(inner) || super::component::is_component_wrapper_call(inner) =>
111	        {
112	            Ok(ArgumentEvidence::Sufficient)
113	        }
114	        _ => Err("is given an argument that is not a render function, a tag or a component reference"),
115	    }
116	}
117	
118	impl<'src> SourceDataCollector<'src> {
119	    pub(super) fn promote_function_aliases(&mut self) {
120	        let aliases = std::mem::take(&mut self.pending_function_aliases);
121	        for _ in 0..aliases.len() {
122	            let mut changed = false;
123	            for (name, target) in &aliases {
124	                let key = self.scoped_key(name);
125	                if self.data.function_results.contains_key(&key) {
126	                    continue;
127	                }
128	                if let Some(result) = self.data.function_results.get(&self.scoped_key(target)).cloned() {
129	                    self.data.function_results.insert(key, result);
130	                    changed = true;
131	                }
132	            }
133	            if !changed {
134	                break;
135	            }
136	        }
137	    }
138	
139	    /// Record `const Name = callee<...>(first, ...)` as a candidate. Returns whether it was recorded.
140	    pub(super) fn try_record_wrapper_call<'a>(&mut self, decl: &super::component::Binding<'_, 'a>, name: &str) -> bool {
141	        let Some(init) = decl.init else { return false };
142	        let Expression::CallExpression(call) = super::component::peel_expr(init) else { return false };
143	        let Some(type_arguments) = call.type_arguments.as_ref() else { return false };
144	        let Some(callee) = self.extract_callee_name(call) else { return false };
145	        let creates_context = self.react_api(&call.callee) == Some(super::ReactApi::CreateContext);
146	        let needs_payload = match component_argument_evidence(creates_context, call, &*self) {
147	            Ok(ArgumentEvidence::Sufficient) => false,
148	            Ok(ArgumentEvidence::TagNeedsPayload) => true,
149	            Err(reason) => {
150	                self.decline_reason = Some(format!("'{name}' is a generic call to '{callee}' that {reason}"));
151	                return false;
152	            }
153	        };
154	        let type_args: Vec<WrapperTypeArg> = type_arguments
155	            .params
156	            .iter()
157	            .map(|ty| WrapperTypeArg { reference: self.extract_type_name_from_type(ty) })
158	            .collect();
159	        let Some(callee) = self.wrapper_callee(call) else { return false };
160	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
161	        self.pending_wrappers.push(PendingWrapper {
162	            name: name.to_owned(),
163	            needs_payload,
164	            tag: None,
165	            type_args,
166	            callee: Some(callee),
167	            rule: DetectionRule::WrapperTypeArgument,
168	            description,
169	            tags,
170	            span: decl.span,
171	        });
172	        true
173	    }
