330	    /// The props type a tagged factory builds from: the interface or alias declared in this file whose heritage or body
331	    /// gives the factory's tag as a type argument, `interface CenterProps extends HTMLChakraProps<"div">` for
332	    /// `chakra("div", …)`, or extends the element's own attributes. Of several, or when other factories in the file
333	    /// share the tag, the one named for the binding. A props type another component in the file takes is not a candidate.
334	    fn tagged_factory_props(
335	        &self,
336	        binding: &str,
337	        tag: &str,
338	        shared_tag: bool,
339	    ) -> Option<(TypeName, Vec<CollectedType>)> {
340	        let prefix = format!("{}:", self.file_path);
341	        let mut found: Vec<TypeName> = Vec::new();
342	        for interface in self.data.interfaces.values().filter(|interface| interface.file_path == self.file_path) {
343	            if interface.extends.iter().any(|extends| extends_gives_tag(extends, tag)) {
344	                found.push(interface.name.clone());
345	            }
346	        }
347	        for (key, alias) in &self.data.type_aliases {
348	            let Some(name) = key.strip_prefix(&prefix) else { continue };
349	            if alias_gives_tag(alias, tag) {
350	                found.push(TypeName::from(name));
351	            }
352	        }
353	        // A props type another component in the file already takes belongs to that component: `StyledGroup =
354	        // chakra("div", …)` is the private recipe `Group` is built on, not a component with `GroupProps`.
355	        found.retain(|name| !self.data.component_mappings.iter().any(|mapping| mapping.props_type_name == *name));
356	        found.sort();
357	        found.dedup();
358	        let wanted = format!("{binding}Props");
359	        let chosen = match found.as_slice() {
360	            [only] if !shared_tag => only.clone(),
361	            _ => found.into_iter().find(|name| name.as_str() == wanted)?,
362	        };
363	        Some((chosen, Vec::new()))
364	    }
