441	/// Whether a type gives `tag` as a type argument: `HTMLChakraProps<"div">`, in an intersection or a union with others.
442	fn gives_tag(ty: &CollectedType, tag: &str) -> bool {
443	    match ty {
444	        CollectedType::Named { args, .. } => args.iter().any(|arg| {
445	            matches!(arg, CollectedType::StringLiteral(value) if value.as_str() == tag) || gives_tag(arg, tag)
446	        }),
447	        CollectedType::Intersection(members) | CollectedType::Union(members) => {
448	            members.iter().any(|member| gives_tag(member, tag))
449	        }
450	        CollectedType::AtFile { inner, .. } => gives_tag(inner, tag),
451	        _ => false,
452	    }
453	}
454	
455	/// Whether a type alias gives `tag`, whatever shape the extractor classified it as: `Omit<ComponentProps<"button">, "x">`
456	/// is an `Omit` of a base that gives it. Every variant is named, so a new one fails to compile here instead of being
457	/// ignored.
458	fn alias_gives_tag(alias: &CollectedTypeAlias, tag: &str) -> bool {
459	    match alias {
460	        CollectedTypeAlias::Passthrough { target: ty, .. }
461	        | CollectedTypeAlias::Omit { base: ty, .. }
462	        | CollectedTypeAlias::Pick { base: ty, .. }
463	        | CollectedTypeAlias::Partial { base: ty, .. }
464	        | CollectedTypeAlias::Required { base: ty, .. } => gives_tag(ty, tag),
465	        CollectedTypeAlias::Union { members, .. } | CollectedTypeAlias::Intersection { members, .. } => {
466	            members.iter().any(|member| gives_tag(member, tag))
467	        }
468	        CollectedTypeAlias::LiteralUnion { .. } => false,
469	    }
470	}
471	
472	/// Whether an `extends` clause gives `tag`: as a type argument, or as the element a built-in attributes type is for.
473	fn extends_gives_tag(extends: &ExtendsRef, tag: &str) -> bool {
474	    let (type_args, element) = match extends {
475	        ExtendsRef::SameFile { type_args, .. } | ExtendsRef::Imported { type_args, .. } => (type_args, None),
476	        ExtendsRef::Builtin { type_args, element, .. } => (type_args, element.as_deref()),
477	    };
478	    element == Some(tag)
479	        || type_args.iter().any(|arg| {
480	            gives_tag(arg, tag) || matches!(arg, CollectedType::StringLiteral(value) if value.as_str() == tag)
481	        })
482	}
