484	/// A single top-level `return Local` where `Local` is a const initialized by a generic call.
485	fn returned_local_call<'a>(collector: &mut SourceDataCollector<'_>, func: &Function<'a>) -> Option<WrapperCallee> {
486	    let body = func.body.as_ref()?;
487	    let mut returns = body.statements.iter().filter_map(|statement| match statement {
488	        Statement::ReturnStatement(ret) => ret.argument.as_ref(),
489	        _ => None,
490	    });
491	    let Expression::Identifier(returned) = returns.next()?.without_parentheses() else { return None };
492	    if returns.next().is_some() {
493	        return None;
494	    }
495	    for statement in &body.statements {
496	        let Statement::VariableDeclaration(declaration) = statement else { continue };
497	        if !declaration.kind.is_const() {
498	            continue;
499	        }
500	        for declarator in &declaration.declarations {
501	            let BindingPattern::BindingIdentifier(name) = &declarator.id else { continue };
502	            if name.name != returned.name {
503	                continue;
504	            }
505	            let Some(Expression::CallExpression(call)) = declarator.init.as_ref().map(super::component::peel_expr)
506	            else {
507	                return None;
508	            };
509	            return collector.wrapper_callee(call);
510	        }
511	    }
512	    None
513	}
