529	/// The type the function's only top-level `return` asserts with `as` (the outermost one of `x as unknown as T`).
530	fn asserted_return_type<'f, 'a>(func: &'f Function<'a>) -> Option<&'f TSType<'a>> {
531	    let mut returns = func.body.as_ref()?.statements.iter().filter_map(|statement| match statement {
532	        Statement::ReturnStatement(ret) => Some(ret.argument.as_ref()),
533	        _ => None,
534	    });
535	    let only = returns.next()??;
536	    if returns.next().is_some() {
537	        return None;
538	    }
539	    match only.without_parentheses() {
540	        Expression::TSAsExpression(assertion) => Some(&assertion.type_annotation),
541	        Expression::TSTypeAssertion(assertion) => Some(&assertion.type_annotation),
542	        _ => None,
543	    }
544	}
