1	//! Evidence that a function renders, so a typed PascalCase function is a component and not a helper that happens to
2	//! take an object. A typed first parameter alone admits `FormatName = (u: User) => string`, `debounce((q: Row) => …)`
3	//! and selectors, so every rule that infers a component from a function asks this first.
4	//!
5	//! What the function returns decides, not what appears anywhere in its body: JSX built in a nested callback or never
6	//! returned is not evidence.
7	
8	use oxc_ast::ast::*;
9	use oxc_ast_visit::{walk, Visit};
10	use oxc_syntax::scope::ScopeFlags;
11	use rustc_hash::FxHashSet;
12	
13	/// Why a function was judged not to render. Carried into the skip diagnostic.
14	pub(super) type NoRender = &'static str;
15	
16	/// Names whose type, as a return annotation, means the function renders.
17	const ELEMENT_TYPE_NAMES: &[&str] = &["Element", "ReactElement", "ReactNode", "ReactPortal", "JSX"];
18	
19	/// Callees that produce an element.
20	const ELEMENT_FACTORIES: &[&str] = &["createElement", "cloneElement", "jsx", "jsxs", "jsxDEV", "createPortal"];
21	
22	/// Whether a type name, as written in this file, can be React's or the global `JSX` namespace's. Given the name's
23	/// leftmost segment (`React` for `React.ReactNode`), so an element-like name imported from another module does not
24	/// count.
25	pub(super) type ReactBinding<'f> = &'f dyn Scope;
26	
27	/// What the file around a function says about the names it uses.
28	pub(super) trait Scope {
29	    /// Whether a type name can be React's: see [`ReactBinding`].
30	    fn may_be_react(&self, name: &str) -> bool;
31	    /// Whether a call to this name returns an element: a same-file function declared to return one.
32	    fn is_element_helper(&self, name: &str) -> bool;
33	    /// Whether the call is React's `memo(…)` or `forwardRef(…)`, by where its callee was imported from.
34	    fn is_react_wrapper(&self, call: &CallExpression<'_>) -> bool;
35	}
36	
37	fn leftmost_and_rightmost<'n>(name: &'n TSTypeName<'_>) -> Option<(&'n str, &'n str)> {
38	    match name {
39	        TSTypeName::IdentifierReference(id) => Some((id.name.as_str(), id.name.as_str())),
40	        TSTypeName::QualifiedName(q) => {
41	            let mut left = &q.left;
42	            while let TSTypeName::QualifiedName(inner) = left {
43	                left = &inner.left;
44	            }
45	            match left {
46	                TSTypeName::IdentifierReference(id) => Some((id.name.as_str(), q.right.name.as_str())),
47	                _ => None,
48	            }
49	        }
50	        _ => None,
51	    }
52	}
53	
54	/// Whether a return type annotation names a renderable result bound to React: `JSX.Element`, `ReactNode`,
55	/// `ReactElement`, a union containing one, or `Promise` of one (async server components).
56	pub(super) fn type_renders(ty: &TSType<'_>, react: ReactBinding<'_>) -> bool {
57	    match ty {
58	        TSType::TSTypeReference(r) => {
59	            let Some((left, right)) = leftmost_and_rightmost(&r.type_name) else { return false };
60	            if right == "Promise" {
61	                return r
62	                    .type_arguments
63	                    .as_ref()
64	                    .and_then(|a| a.params.first())
65	                    .is_some_and(|t| type_renders(t, react));
66	            }
67	            ELEMENT_TYPE_NAMES.contains(&right) && react.may_be_react(left)
68	        }
69	        TSType::TSUnionType(u) => u.types.iter().any(|t| type_renders(t, react)),
70	        TSType::TSParenthesizedType(p) => type_renders(&p.type_annotation, react),
71	        _ => false,
72	    }
73	}
74	
75	fn callee_name<'n>(callee: &'n Expression<'_>) -> Option<&'n str> {
76	    match callee {
77	        Expression::Identifier(id) => Some(id.name.as_str()),
78	        Expression::StaticMemberExpression(m) => Some(m.property.name.as_str()),
79	        _ => None,
80	    }
81	}
