83	fn is_hook_name(name: &str) -> bool {
84	    name.strip_prefix("use").is_some_and(|rest| rest.starts_with(|c: char| c.is_ascii_uppercase()))
85	}
86	
87	fn is_children(expr: &Expression<'_>) -> bool {
88	    match expr {
89	        Expression::Identifier(id) => id.name == "children",
90	        Expression::StaticMemberExpression(m) => m.property.name == "children",
91	        _ => false,
92	    }
93	}
