95	/// Finds JSX or an element factory call that can be part of an expression's value: through conditionals, logical
96	/// operators, arrays and call arguments (`items.map(i => <li/>)`, `createPortal(<div/>, el)`), but not inside an object
97	/// literal, whose JSX is a property's value rather than the expression's.
98	struct ElementInValue<'s> {
99	    found: bool,
100	    scope: &'s dyn Scope,
101	}
102	
103	impl<'a> Visit<'a> for ElementInValue<'_> {
104	    fn visit_jsx_element(&mut self, _it: &JSXElement<'a>) {
105	        self.found = true;
106	    }
107	
108	    fn visit_jsx_fragment(&mut self, _it: &JSXFragment<'a>) {
109	        self.found = true;
110	    }
111	
112	    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
113	        let name = callee_name(&it.callee);
114	        let calls_helper = matches!(&it.callee, Expression::Identifier(id) if self.scope.is_element_helper(&id.name));
115	        if calls_helper || name.is_some_and(|c| ELEMENT_FACTORIES.contains(&c)) {
116	            self.found = true;
117	        // These calls preserve the JSX value; an arbitrary call may turn it into a Response or other data.
118	        } else if name.is_some_and(|name| matches!(name, "map" | "flatMap" | "reduce"))
119	            || matches!(&it.callee, Expression::StaticMemberExpression(member)
120	                if matches!(&member.object, Expression::Identifier(id) if id.name == "Promise")
121	                    && matches!(member.property.name.as_str(), "resolve" | "all"))
122	        {
123	            walk::walk_call_expression(self, it);
124	        }
125	    }
126	
127	    // JSX passed to a constructor, such as `new ImageResponse(<div />)`, is not the function's return value.
128	    fn visit_new_expression(&mut self, _it: &NewExpression<'a>) {}
129	
130	    fn visit_object_expression(&mut self, _it: &ObjectExpression<'a>) {}
131	}
132	
133	fn value_has_element(expr: &Expression<'_>, scope: &dyn Scope) -> bool {
134	    let mut finder = ElementInValue { found: false, scope };
135	    finder.visit_expression(expr);
136	    finder.found
137	}
138	
139	/// What one returned value says about the function.
140	fn returns_element(expr: &Expression<'_>, element_locals: &FxHashSet<String>, scope: &dyn Scope) -> bool {
141	    match expr.without_parentheses() {
142	        // Rendering nothing is a valid render.
143	        Expression::NullLiteral(_) => true,
144	        Expression::Identifier(id) if element_locals.contains(id.name.as_str()) => true,
145	        // A component invoked directly: `return JoinList({ ... })`.
146	        Expression::CallExpression(call)
147	            if callee_name(&call.callee).is_some_and(|n| n.starts_with(|c: char| c.is_ascii_uppercase())) =>
148	        {
149	            true
150	        }
151	        e if is_children(e) => true,
152	        e => value_has_element(e, scope),
153	    }
154	}
155	
156	/// Walks one function's own body, not nested functions: its `return`s, its top-level hook calls, and the local
157	/// variables it initializes with an element (`const content = <div/>; return content`).
158	/// A local is declared before the `return` that uses it, so each `return` is judged as it is reached.
159	struct OwnBody<'s> {
160	    returns_element: bool,
161	    element_locals: FxHashSet<String>,
162	    calls_hook: bool,
163	    nested: u32,
164	    scope: &'s dyn Scope,
165	}
166	
167	impl<'s> OwnBody<'s> {
168	    fn new(scope: &'s dyn Scope) -> Self {
169	        Self { returns_element: false, element_locals: FxHashSet::default(), calls_hook: false, nested: 0, scope }
170	    }
171	}
172	
173	impl<'a> Visit<'a> for OwnBody<'_> {
174	    fn visit_return_statement(&mut self, it: &ReturnStatement<'a>) {
175	        if self.nested == 0
176	            && it.argument.as_ref().is_some_and(|r| returns_element(r, &self.element_locals, self.scope))
177	        {
178	            self.returns_element = true;
179	        }
180	        walk::walk_return_statement(self, it);
181	    }
182	
183	    fn visit_variable_declarator(&mut self, it: &VariableDeclarator<'a>) {
184	        if self.nested == 0 {
185	            if let (BindingPattern::BindingIdentifier(id), Some(init)) = (&it.id, &it.init) {
186	                if value_has_element(init, self.scope) {
187	                    self.element_locals.insert(id.name.to_string());
188	                }
189	            }
190	        }
191	        walk::walk_variable_declarator(self, it);
192	    }
193	
194	    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
195	        if self.nested == 0 && callee_name(&it.callee).is_some_and(is_hook_name) {
196	            self.calls_hook = true;
197	        }
198	        walk::walk_call_expression(self, it);
199	    }
200	
201	    fn visit_function(&mut self, it: &Function<'a>, flags: ScopeFlags) {
202	        self.nested += 1;
203	        walk::walk_function(self, it, flags);
204	        self.nested -= 1;
205	    }
206	
207	    fn visit_arrow_function_expression(&mut self, it: &ArrowFunctionExpression<'a>) {
208	        self.nested += 1;
209	        walk::walk_arrow_function_expression(self, it);
210	        self.nested -= 1;
211	    }
212	}
213	
214	/// A function body: a block, or an arrow's single expression or block.
215	pub(super) enum Body<'b, 'a> {
216	    Block(&'b FunctionBody<'a>),
217	    /// An arrow's body, and whether it is a single expression (`=> <div/>`) rather than a block.
218	    Arrow(&'b ArrowFunctionBody<'a>, bool),
219	}
220	
221	/// The parts of a function that decide whether it renders.
222	pub(super) struct FunctionShape<'b, 'a> {
223	    pub generator: bool,
224	    pub return_type: Option<&'b TSTypeAnnotation<'a>>,
225	    pub body: Option<Body<'b, 'a>>,
226	}
227	
228	impl<'b, 'a> FunctionShape<'b, 'a> {
229	    pub(super) fn of_arrow(f: &'b ArrowFunctionExpression<'a>) -> Self {
230	        Self {
231	            generator: false,
232	            return_type: f.return_type.as_deref(),
233	            body: Some(Body::Arrow(&f.body, f.is_expression())),
234	        }
235	    }
236	
237	    pub(super) fn of_function(f: &'b Function<'a>) -> Self {
238	        Self { generator: f.generator, return_type: f.return_type.as_deref(), body: f.body.as_deref().map(Body::Block) }
239	    }
240	}
241	
242	/// `Ok` when the function renders; `Err` with the reason it does not.
243	pub(super) fn renders(shape: &FunctionShape<'_, '_>, react: ReactBinding<'_>) -> Result<(), NoRender> {
244	    if shape.generator {
245	        return Err("is a generator");
246	    }
247	    if let Some(annotation) = shape.return_type {
248	        return if type_renders(&annotation.type_annotation, react) {
249	            Ok(())
250	        } else {
251	            Err("declares a return type that is not React's element type")
252	        };
253	    }
254	    let renders = match &shape.body {
255	        None => return Err("has no body and no element return type"),
256	        Some(Body::Arrow(body, true)) => {
257	            body.as_expression().is_some_and(|expr| returns_element(expr, &FxHashSet::default(), react))
258	        }
259	        Some(Body::Arrow(body, false)) => {
260	            let mut own = OwnBody::new(react);
261	            own.visit_arrow_function_body(body);
262	            own.calls_hook || own.returns_element
263	        }
264	        Some(Body::Block(body)) => {
265	            let mut own = OwnBody::new(react);
266	            own.visit_function_body(body);
267	            own.calls_hook || own.returns_element
268	        }
269	    };
270	    if renders {
271	        Ok(())
272	    } else {
273	        Err("never returns an element: no returned JSX, element, null, children or component call, and no hook call")
274	    }
275	}
