277	/// Names of module-level functions whose declared return type is an element, which makes a call to them element
278	/// evidence: `renderByProp(render, props, <button />)` with `renderByProp(...): React.ReactElement`. Judged on the
279	/// declaration alone, so a helper that returns something else without saying so is not counted.
280	pub(super) fn element_helpers(program: &Program<'_>) -> FxHashSet<String> {
281	    let mut foreign = FxHashSet::default();
282	    for stmt in &program.body {
283	        if let Statement::ImportDeclaration(import) = stmt {
284	            if import.source.value != "react" && !import.source.value.starts_with("react/") {
285	                for spec in import.specifiers.iter().flatten() {
286	                    foreign.insert(spec.local().name.to_string());
287	                }
288	            }
289	        }
290	    }
291	    let react = Foreign(&foreign);
292	    let declarations: Vec<&Declaration<'_>> = program.body.iter().filter_map(|stmt| stmt.as_declaration()).collect();
293	
294	    // `type Output = React.ReactElement` and aliases of aliases.
295	    let mut aliases = FxHashSet::default();
296	    loop {
297	        let before = aliases.len();
298	        for declaration in &declarations {
299	            if let Declaration::TSTypeAliasDeclaration(alias) = declaration {
300	                if names_element(&alias.type_annotation, &react, &aliases) {
301	                    aliases.insert(alias.id.name.to_string());
302	                }
303	            }
304	        }
305	        if aliases.len() == before {
306	            break;
307	        }
308	    }
309	
310	    let returns_element = |annotation: Option<&TSTypeAnnotation<'_>>| {
311	        annotation.is_some_and(|a| names_element(&a.type_annotation, &react, &aliases))
312	    };
313	    let mut helpers = FxHashSet::default();
314	    for declaration in declarations {
315	        match declaration {
316	            Declaration::FunctionDeclaration(f) => {
317	                if let Some(id) = f.id.as_ref().filter(|_| returns_element(f.return_type.as_deref())) {
318	                    helpers.insert(id.name.to_string());
319	                }
320	            }
321	            Declaration::VariableDeclaration(vars) => {
322	                for declarator in &vars.declarations {
323	                    let (BindingPattern::BindingIdentifier(id), Some(init)) = (&declarator.id, &declarator.init) else {
324	                        continue;
325	                    };
326	                    let annotation = match init.without_parentheses() {
327	                        Expression::ArrowFunctionExpression(f) => f.return_type.as_deref(),
328	                        Expression::FunctionExpression(f) => f.return_type.as_deref(),
329	                        _ => None,
330	                    };
331	                    if returns_element(annotation) {
332	                        helpers.insert(id.name.to_string());
333	                    }
334	                }
335	            }
336	            _ => {}
337	        }
338	    }
339	    helpers
340	}
341	
342	/// The imports that are not React's, seen before the file is walked.
343	struct Foreign<'f>(&'f FxHashSet<String>);
344	
345	impl Scope for Foreign<'_> {
346	    fn may_be_react(&self, name: &str) -> bool {
347	        !self.0.contains(name)
348	    }
349	
350	    fn is_element_helper(&self, _name: &str) -> bool {
351	        false
352	    }
353	
354	    fn is_react_wrapper(&self, _call: &CallExpression<'_>) -> bool {
355	        false
356	    }
357	}
358	
359	/// Whether a type is an element type or a local alias of one. A `Promise` of one is not: the call returns the promise.
360	fn names_element(ty: &TSType<'_>, react: ReactBinding<'_>, aliases: &FxHashSet<String>) -> bool {
361	    match ty {
362	        TSType::TSTypeReference(r) => match &r.type_name {
363	            TSTypeName::IdentifierReference(id) if aliases.contains(id.name.as_str()) => true,
364	            name => {
365	                leftmost_and_rightmost(name).is_some_and(|(_, right)| right != "Promise") && type_renders(ty, react)
366	            }
367	        },
368	        TSType::TSUnionType(u) => u.types.iter().any(|t| names_element(t, react, aliases)),
369	        TSType::TSParenthesizedType(p) => names_element(&p.type_annotation, react, aliases),
370	        _ => false,
371	    }
372	}
