1	//! How each name is used and exported in its file. A function that only looks like a component is not reported as one:
2	//! a helper that is only ever called (`IndexedAccess(type)`), or a render callback that takes a ref and is never
3	//! rendered (`{render: TableDropIndicatorWrapper}`). Every component records whether its module exports it.
4	
5	use compact_str::CompactString;
6	use oxc_ast::ast::*;
7	use oxc_span::Span;
8	
9	use crate::types::DiagnosticCode;
10	
11	use super::SourceDataCollector;
12	
13	/// The references to one name in a file.
14	#[derive(Default, Clone, Copy)]
15	pub(crate) struct NameUses {
16	    references: u32,
17	    /// References that are the callee of a call: `Name(...)`.
18	    calls: u32,
19	    /// References that render it: a JSX tag, or the first argument of `createElement` or a component wrapper.
20	    rendered: u32,
21	}
22	
23	impl<'src> SourceDataCollector<'src> {
24	    fn uses_of(&mut self, name: &str) -> &mut NameUses {
25	        self.name_uses.entry(CompactString::from(name)).or_default()
26	    }
27	
28	    pub(super) fn record_reference(&mut self, reference: &IdentifierReference<'_>) {
29	        self.uses_of(reference.name.as_str()).references += 1;
30	    }
31	
32	    /// A local name the module exports (`export function Name`, `export { Name as Other }`, `export default Name`).
33	    pub(super) fn record_exported_local(&mut self, name: &str) {
34	        self.exported_locals.insert(CompactString::from(name));
35	    }
36	
37	    /// `Parent.Sub = Sub` or `Object.assign(Parent, { Sub: Sub })`.
38	    pub(super) fn record_attached(&mut self, sub: &str, parent: &str) {
39	        self.attached_to.push((CompactString::from(sub), CompactString::from(parent)));
40	    }
41	
42	    /// `const Parent = Object.assign(Root, { Sub })`: `Parent` is the root under another name, with `Sub` attached.
43	    pub(super) fn record_object_assign_declarator(&mut self, parent: &str, init: Option<&Expression<'_>>) {
44	        let Some(Expression::CallExpression(call)) = init.map(super::component::peel_expr) else { return };
45	        let Expression::StaticMemberExpression(callee) = &call.callee else { return };
46	        if !matches!(&callee.object, Expression::Identifier(object) if object.name == "Object")
47	            || callee.property.name != "assign"
48	        {
49	            return;
50	        }
51	        for argument in &call.arguments {
52	            match argument.as_expression().map(super::component::peel_expr) {
53	                Some(Expression::Identifier(root)) => self.record_attached(root.name.as_str(), parent),
54	                Some(Expression::ObjectExpression(object)) => {
55	                    for property in &object.properties {
56	                        let ObjectPropertyKind::ObjectProperty(property) = property else { continue };
57	                        if let Expression::Identifier(sub) = super::component::peel_expr(&property.value) {
58	                            self.record_attached(sub.name.as_str(), parent);
59	                        }
60	                    }
61	                }
62	                _ => {}
63	            }
64	        }
65	    }
66	
67	    /// `Parent.Sub = Sub` at statement level.
68	    pub(super) fn record_member_assignment(&mut self, statement: &ExpressionStatement<'_>) {
69	        let Expression::AssignmentExpression(assignment) = &statement.expression else { return };
70	        let AssignmentTarget::StaticMemberExpression(target) = &assignment.left else { return };
71	        let (Expression::Identifier(parent), Expression::Identifier(sub)) =
72	            (&target.object, super::component::peel_expr(&assignment.right))
73	        else {
74	            return;
75	        };
76	        self.record_attached(sub.name.as_str(), parent.name.as_str());
77	    }
78	
79	    /// The names of the file's exported components: the exported locals, and any component attached to an exported
80	    /// one, transitively.
81	    pub(super) fn exported_components(&self) -> rustc_hash::FxHashSet<CompactString> {
82	        let mut exported = self.exported_locals.clone();
83	        loop {
84	            let before = exported.len();
85	            for (sub, parent) in &self.attached_to {
86	                if exported.contains(parent) {
87	                    exported.insert(sub.clone());
88	                }
89	            }
90	            if exported.len() == before {
91	                return exported;
92	            }
93	        }
94	    }
95	
96	    pub(super) fn record_call(&mut self, call: &CallExpression<'_>) {
97	        if let Expression::Identifier(callee) = super::component::peel_expr(&call.callee) {
98	            self.uses_of(callee.name.as_str()).calls += 1;
99	        }
100	        let renders_argument = super::evidence::Scope::is_react_wrapper(&*self, call)
101	            || super::component::is_component_wrapper_call(call)
102	            || matches!(
103	                super::component::peel_expr(&call.callee),
104	                Expression::Identifier(id) if id.name == "createElement"
105	            )
106	            || matches!(
107	                super::component::peel_expr(&call.callee),
108	                Expression::StaticMemberExpression(m) if m.property.name == "createElement"
109	            );
110	        if renders_argument {
111	            if let Some(Argument::Identifier(component)) = call.arguments.first() {
112	                self.uses_of(component.name.as_str()).rendered += 1;
113	            }
114	        }
115	    }
116	
117	    pub(super) fn record_jsx_element(&mut self, element: &JSXOpeningElement<'_>) {
118	        if let JSXElementName::IdentifierReference(component) = &element.name {
119	            self.uses_of(component.name.as_str()).rendered += 1;
120	        }
121	    }
122	
123	    /// Drop the component candidates that are not exported and are used only as functions: every reference is a call,
124	    /// or they take a second parameter (a ref) and are never rendered. Each is reported as a skipped candidate.
125	    pub(super) fn drop_functions_used_only_as_functions(&mut self, exported: &rustc_hash::FxHashSet<CompactString>) {
126	        let mut dropped: Vec<(String, String, Span)> = Vec::new();
127	        for mapping in &self.data.component_mappings {
128	            let name = mapping.component_name.as_str();
129	            if exported.contains(name) {
130	                continue;
131	            }
132	            let uses = self.name_uses.get(name).copied().unwrap_or_default();
133	            let reason = if uses.calls > 0 && uses.references == uses.calls {
134	                "is only ever called as a function in this file, never rendered or passed on, so it is a helper"
135	            } else if self.takes_a_second_parameter.contains(name) && uses.rendered == 0 {
136	                "takes a second parameter (a ref) and is never rendered or passed to a component wrapper in this \
137	                 file, so it is a render callback"
138	            } else {
139	                continue;
140	            };
141	            dropped.push((name.to_owned(), reason.to_owned(), Span::new(mapping.span_start, mapping.span_end)));
142	        }
143	        for (name, reason, span) in dropped {
144	            self.data.component_mappings.retain(|m| m.component_name != name);
145	            self.record_skip(DiagnosticCode::SkippedCandidate, format!("'{name}' {reason}, not a component"), span);
146	        }
147	    }
148	}
