1	//! The props of a component a generic call builds, read from what the callee returns.
2	//!
3	//! `const Button = factory<ButtonFactory>(render)` is whatever `factory` returns. With the callee's type parameters
4	//! bound to the call's type arguments, the props parameter of the React component type in its result is the
5	//! component's props, as TypeScript (and react-docgen-typescript) reads them: Mantine's `factory` returns
6	//! `MantineComponent<Payload>`, whose props are `Payload['props']` plus `component` and `renderRoot`. The extractor's
7	//! choice among the type arguments (`extractor/wrapper.rs`) is the fallback for a callee with no known result. Nothing
8	//! here names a library; the React component types are React's own.
9	
10	use std::sync::Arc;
11	
12	use camino::{Utf8Path, Utf8PathBuf};
13	
14	use crate::types::*;
15	
16	use super::alias::resolve_base_as_chain;
17	use super::import::{lookup_interface, lookup_type_alias, resolve_to_canonical};
18	use super::substitute::{build_substitution, substitute_alias, substitute_type};
19	use super::ResolutionContext;
20	
21	/// React types whose first type argument is a component's props.
22	const COMPONENT_TYPES: &[&str] = &[
23	    "NamedExoticComponent",
24	    "ForwardRefExoticComponent",
25	    "ExoticComponent",
26	    "FC",
27	    "FunctionComponent",
28	    "VFC",
29	    "VoidFunctionComponent",
30	    "ComponentType",
31	    "JSXElementConstructor",
32	];
33	
34	/// Aliases followed from the result type to the component type; the bound only guards against a cycle.
35	const MAX_DEPTH: u8 = 8;
36	
37	pub(super) fn component_props_of_typeof(
38	    name: &str,
39	    file: &Utf8Path,
40	    ctx: &ResolutionContext,
41	) -> Option<(CollectedType, Utf8PathBuf)> {
42	    component_props_type(&CollectedType::TypeOf(name.into()), file, ctx, 0).map(|(props, file, _)| (props, file))
43	}
44	
45	/// The props chain of the component a generic call builds, from its callee's result type. `None` when the callee is
46	/// not a project function with a known result, the result has no React component type, or its props evaluate to
47	/// nothing (a conditional over an unbound generic, as in Mantine's `polymorphicFactory`): the extractor's selection
48	/// is then the closer answer.
49	pub(super) fn result_chain(
50	    mapping: &ComponentMapping,
51	    ctx: &ResolutionContext,
52	    state: &mut ResolveState,
53	) -> Option<super::ResolvedChain> {
54	    let callee = mapping.wrapper_callee.as_ref()?;
55	    let (props, props_file, type_params, factory_params) = result_props(callee, &mapping.file_path, ctx, 0)?;
56	    let mut attempt = state.branch();
57	    attempt.add_type_params(type_params.iter());
58	    attempt.add_type_params(factory_params.iter());
59	    let mut chain = resolve_base_as_chain(&props, &props_file, mapping, ctx, &mut attempt, 0);
60	    if chain
61	        .composes
62	        .iter()
63	        .any(|name| factory_params.iter().any(|param| name == param.as_str() || name.starts_with(&format!("{param}["))))
64	    {
65	        let fallback = super::chain::resolve_props_chain(
66	            mapping.props_type_name.as_str(),
67	            &mapping.props_type_args,
68	            &mapping.file_path,
69	            mapping,
70	            ctx,
71	            &mut attempt,
72	            0,
73	        );
74	        // An explicit `any` from the selected payload absorbs the conditional's tentative type in an intersection.
75	        for prop in &fallback.props {
76	            if matches!(prop.prop_type, PropType::Any) {
77	                if let Some(existing) = chain.props.iter_mut().find(|existing| existing.name == prop.name) {
78	                    *existing = Arc::clone(prop);
79	                }
80	            }
81	        }
82	        chain.merge_parent(fallback);
83	    }
84	    if chain.props.is_empty() && chain.inheritance.is_empty() {
85	        return None;
86	    }
87	    erase_unbound_params(&mut chain, type_params.iter().chain(&factory_params));
88	    state.absorb(attempt);
89	    Some(chain)
90	}
91	
92	/// A type parameter of the factory or of its result's call signature, beside other members of a union, stands for one
93	/// of them (`C | ElementType` with `C extends ElementType`), and its bare name tells a reader nothing, so the union
94	/// keeps the other members.
95	fn erase_unbound_params<'p>(chain: &mut super::ResolvedChain, params: impl Iterator<Item = &'p TypeName> + Clone) {
96	    let is_param = |member: &PropType| {
97	        matches!(member, PropType::Named { name, args }
98	            if args.is_empty() && params.clone().any(|p| p.as_str() == name.as_str()))
99	    };
100	    for prop in &mut chain.props {
101	        let PropType::Union(members) = &prop.prop_type else { continue };
102	        if !members.iter().any(is_param) {
103	            continue;
104	        }
105	        let kept: Vec<PropType> = members.iter().filter(|member| !is_param(member)).cloned().collect();
106	        if kept.is_empty() {
107	            continue;
108	        }
109	        let mut edited = (**prop).clone();
110	        edited.prop_type = super::primitives::union_of(kept);
111	        *prop = Arc::new(edited);
112	    }
113	}
114	
115	fn result_props(
116	    callee: &WrapperCallee,
117	    caller_file: &Utf8Path,
118	    ctx: &ResolutionContext,
119	    depth: u8,
120	) -> Option<(CollectedType, Utf8PathBuf, Vec<TypeName>, Vec<TypeName>)> {
121	    if depth > MAX_DEPTH {
122	        return None;
123	    }
124	    let mut ignored = Vec::new();
125	    let (file, name) = resolve_to_canonical(&callee.name, caller_file, ctx, &mut ignored)
126	        .unwrap_or_else(|| (caller_file.to_owned(), callee.name.to_string()));
127	    super::deps::record(&file);
128	    let function = ctx.global.function_results.get(&format!("{file}:{name}"))?;
129	    let bindings = build_substitution(&function.type_params, &callee.type_args, caller_file, &mut ignored);
130	    if let Some(inner) = &function.returned_call {
131	        let inner = WrapperCallee {
132	            name: inner.name.clone(),
133	            type_args: inner.type_args.iter().map(|arg| substitute_type(arg, &bindings)).collect(),
134	        };
135	        return result_props(&inner, &file, ctx, depth + 1);
136	    }
137	    let result = substitute_type(&function.result, &bindings);
138	    let (props, props_file, type_params) = component_props_type(&result, &file, ctx, 0)?;
