229	/// The props parameter of the React component type `ty` describes, its file, and any callable type parameters in scope.
230	fn component_props_type(
231	    ty: &CollectedType,
232	    file: &Utf8Path,
233	    ctx: &ResolutionContext,
234	    depth: u8,
235	) -> Option<(CollectedType, Utf8PathBuf, Vec<TypeName>)> {
236	    if depth > MAX_DEPTH {
237	        return None;
238	    }
239	    match ty {
240	        CollectedType::AtFile { file, inner } => component_props_type(inner, file, ctx, depth + 1),
241	        CollectedType::TypeOf(name) => {
242	            let mut ignored = Vec::new();
243	            let (canonical_file, canonical_name) = resolve_to_canonical(name, file, ctx, &mut ignored)
244	                .unwrap_or_else(|| (file.to_owned(), name.to_string()));
245	            let mapping = ctx
246	                .component_mapping(&canonical_file, &canonical_name)
247	                .or_else(|| ctx.dependencies.as_ref()?.component(&canonical_file, &canonical_name));
248	            let Some(mapping) = mapping else {
249	                let (base, member) = name.rsplit_once('.')?;
250	                let (props, props_file) = value_member_props_at_depth(base, member, file, ctx, depth + 1)?;
251	                return Some((props, props_file, Vec::new()));
252	            };
253	            Some((
254	                CollectedType::Named {
255	                    name: mapping.props_type_name.clone(),
256	                    args: super::extends::instantiated_props_args(mapping),
257	                },
258	                mapping.file_path.clone(),
259	                mapping.type_params.clone(),
260	            ))
261	        }
262	        CollectedType::Intersection(members) => {
263	            members.iter().find_map(|member| component_props_type(member, file, ctx, depth + 1))
264	        }
265	        CollectedType::Function { type_params, params, .. } => {
266	            Some((params.first()?.clone(), file.to_owned(), type_params.clone()))
267	        }
268	        CollectedType::Named { name, args } => {
269	            if COMPONENT_TYPES.contains(&name.strip_prefix("React.").unwrap_or(name)) {
270	                return Some((args.first()?.clone(), file.to_owned(), Vec::new()));
271	            }
272	            let mut ignored = Vec::new();
273	            let (alias_file, alias_name) = resolve_to_canonical(name, file, ctx, &mut ignored)
274	                .unwrap_or_else(|| (file.to_owned(), name.to_string()));
275	            // `interface PrimitiveForwardRefComponent<E> extends React.ForwardRefExoticComponent<Props<E>> {}`.
276	            if let Some(iface) = lookup_interface(ctx, alias_file.as_str(), &alias_name) {
277	                let bindings = ctx
278	                    .named_types
279	                    .lookup_interface_type_params_for(iface)
280	                    .map(|params| build_substitution(params, args, file, &mut ignored));
281	                return iface.extends.iter().find_map(|extends| {
282	                    let (ExtendsRef::SameFile { name: base, type_args }
283	                    | ExtendsRef::Imported { local_name: base, type_args, .. }
284	                    | ExtendsRef::Builtin { name: base, type_args, .. }) = extends;
285	                    if !COMPONENT_TYPES.contains(&base.strip_prefix("React.").unwrap_or(base)) {
286	                        return None;
287	                    }
288	                    let props = type_args.first()?;
289	                    let props = bindings.as_ref().map_or_else(|| props.clone(), |b| substitute_type(props, b));
290	                    Some((props, alias_file.clone(), Vec::new()))
291	                });
292	            }
293	            let (matched, alias) = lookup_type_alias(ctx, alias_file.as_str(), &alias_name)?;
294	            let alias = match ctx.named_types.lookup_type_alias_params(&alias_file, &matched) {
295	                Some(params) => substitute_alias(alias, &build_substitution(params, args, file, &mut ignored)),
296	                None => alias.clone(),
297	            };
298	            let body = match alias {
299	                CollectedTypeAlias::Passthrough { target, .. } => target,
300	                CollectedTypeAlias::Intersection { members, .. } => CollectedType::Intersection(members),
301	                _ => return None,
302	            };
303	            component_props_type(&body, &alias_file, ctx, depth + 1)
304	        }
305	        _ => None,
306	    }
307	}
