21	/// React types whose first type argument is a component's props.
22	const COMPONENT_TYPES: &[&str] = &[
23	    "NamedExoticComponent",
24	    "ForwardRefExoticComponent",
25	    "ExoticComponent",
26	    "FC",
27	    "FunctionComponent",
28	    "VFC",
29	    "VoidFunctionComponent",
30	    "ComponentType",
31	    "JSXElementConstructor",
32	];
