37	pub(super) fn component_props_of_typeof(
38	    name: &str,
39	    file: &Utf8Path,
40	    ctx: &ResolutionContext,
41	) -> Option<(CollectedType, Utf8PathBuf)> {
42	    component_props_type(&CollectedType::TypeOf(name.into()), file, ctx, 0).map(|(props, file, _)| (props, file))
43	}
