45	/// The props chain of the component a generic call builds, from its callee's result type. `None` when the callee is
46	/// not a project function with a known result, the result has no React component type, or its props evaluate to
47	/// nothing (a conditional over an unbound generic, as in Mantine's `polymorphicFactory`): the extractor's selection
48	/// is then the closer answer.
49	pub(super) fn result_chain(
50	    mapping: &ComponentMapping,
51	    ctx: &ResolutionContext,
52	    state: &mut ResolveState,
53	) -> Option<super::ResolvedChain> {
54	    let callee = mapping.wrapper_callee.as_ref()?;
55	    let (props, props_file, type_params, factory_params) = result_props(callee, &mapping.file_path, ctx, 0)?;
56	    let mut attempt = state.branch();
57	    attempt.add_type_params(type_params.iter());
58	    attempt.add_type_params(factory_params.iter());
59	    let mut chain = resolve_base_as_chain(&props, &props_file, mapping, ctx, &mut attempt, 0);
60	    if chain
61	        .composes
62	        .iter()
63	        .any(|name| factory_params.iter().any(|param| name == param.as_str() || name.starts_with(&format!("{param}["))))
64	    {
65	        let fallback = super::chain::resolve_props_chain(
66	            mapping.props_type_name.as_str(),
67	            &mapping.props_type_args,
68	            &mapping.file_path,
69	            mapping,
70	            ctx,
71	            &mut attempt,
72	            0,
73	        );
74	        // An explicit `any` from the selected payload absorbs the conditional's tentative type in an intersection.
75	        for prop in &fallback.props {
76	            if matches!(prop.prop_type, PropType::Any) {
77	                if let Some(existing) = chain.props.iter_mut().find(|existing| existing.name == prop.name) {
78	                    *existing = Arc::clone(prop);
79	                }
80	            }
81	        }
82	        chain.merge_parent(fallback);
83	    }
84	    if chain.props.is_empty() && chain.inheritance.is_empty() {
85	        return None;
86	    }
87	    erase_unbound_params(&mut chain, type_params.iter().chain(&factory_params));
88	    state.absorb(attempt);
89	    Some(chain)
90	}
