92	/// A type parameter of the factory or of its result's call signature, beside other members of a union, stands for one
93	/// of them (`C | ElementType` with `C extends ElementType`), and its bare name tells a reader nothing, so the union
94	/// keeps the other members.
95	fn erase_unbound_params<'p>(chain: &mut super::ResolvedChain, params: impl Iterator<Item = &'p TypeName> + Clone) {
96	    let is_param = |member: &PropType| {
97	        matches!(member, PropType::Named { name, args }
98	            if args.is_empty() && params.clone().any(|p| p.as_str() == name.as_str()))
99	    };
100	    for prop in &mut chain.props {
101	        let PropType::Union(members) = &prop.prop_type else { continue };
102	        if !members.iter().any(is_param) {
103	            continue;
104	        }
105	        let kept: Vec<PropType> = members.iter().filter(|member| !is_param(member)).cloned().collect();
106	        if kept.is_empty() {
107	            continue;
108	        }
109	        let mut edited = (**prop).clone();
110	        edited.prop_type = super::primitives::union_of(kept);
111	        *prop = Arc::new(edited);
112	    }
113	}
