115	fn result_props(
116	    callee: &WrapperCallee,
117	    caller_file: &Utf8Path,
118	    ctx: &ResolutionContext,
119	    depth: u8,
120	) -> Option<(CollectedType, Utf8PathBuf, Vec<TypeName>, Vec<TypeName>)> {
121	    if depth > MAX_DEPTH {
122	        return None;
123	    }
124	    let mut ignored = Vec::new();
125	    let (file, name) = resolve_to_canonical(&callee.name, caller_file, ctx, &mut ignored)
