144	/// type is the mapped type's value with the key variable bound to the member name, and its props are those of the
145	/// React component type that describes. `base` is the value as `file` writes it.
146	pub(super) fn value_member_props(
147	    base: &str,
148	    member: &str,
149	    file: &Utf8Path,
