155	fn value_member_props_at_depth(
156	    base: &str,
157	    member: &str,
158	    file: &Utf8Path,
159	    ctx: &ResolutionContext,
160	    depth: u8,
161	) -> Option<(CollectedType, Utf8PathBuf)> {
162	    if depth > MAX_DEPTH {
163	        return None;
164	    }
165	    let mut ignored = Vec::new();
166	    let (base_file, base_name) =
167	        resolve_to_canonical(base, file, ctx, &mut ignored).unwrap_or_else(|| (file.to_owned(), base.to_owned()));
168	    let (base_file, base_name, member) =
169	        if lookup_type_alias(ctx, base_file.as_str(), &format!("typeof {base_name}")).is_some() {
170	            (base_file, base_name, member.to_owned())
171	        } else if let Some(Some((declaring_file, qualified))) =
172	            ctx.dependencies.as_ref().and_then(|layer| layer.export_of(&base_file, &format!("{base_name}.{member}")))
173	        {
174	            let (declaring_name, declared_member) = qualified.split_once('.')?;
175	            (declaring_file.clone(), declaring_name.to_owned(), declared_member.to_owned())
176	        } else {
177	            let local = ctx.import_map.local_export(&base_file, &base_name)?;
178	            let (file, name) = resolve_to_canonical(&local, &base_file, ctx, &mut ignored)?;
179	            (file, name, member.to_owned())
180	        };
181	    let (_, declared) = lookup_type_alias(ctx, base_file.as_str(), &format!("typeof {base_name}"))?;
182	    let name = match declared {
183	        CollectedTypeAlias::Passthrough { target: named @ CollectedType::Named { .. }, .. } => {
184	            if let Some((member_type, member_file)) = super::evaluate::member(named, &member, &base_file, ctx, 0) {
185	                if let Some((props, file, _)) = component_props_type(&member_type, &member_file, ctx, depth + 1) {
186	                    return Some((props, file));
187	                }
188	            }
189	            let CollectedType::Named { name, .. } = named else { return None };
190	            name
191	        }
192	        CollectedTypeAlias::Passthrough { target: CollectedType::Object(fields), .. } => {
193	            return fields
194	                .iter()
195	                .find(|field| field.is_member() && field.name == member)
196	                .and_then(|field| component_props_type(&field.collected_type, &base_file, ctx, depth + 1))
197	                .map(|(props, file, _)| (props, file));
198	        }
199	        CollectedTypeAlias::Passthrough { target: CollectedType::Intersection(members), .. } => {
200	            return members.iter().find_map(|part| match part {
201	                CollectedType::Object(fields) => fields
202	                    .iter()
203	                    .find(|field| field.is_member() && field.name == member)
204	                    .and_then(|field| component_props_type(&field.collected_type, &base_file, ctx, depth + 1))
205	                    .map(|(props, file, _)| (props, file)),
206	                _ => None,
207	            });
208	        }
209	        _ => return None,
210	    };
211	    let (mapped_file, mapped_name) = resolve_to_canonical(name, &base_file, ctx, &mut ignored)
212	        .unwrap_or_else(|| (base_file.clone(), name.to_string()));
213	    let (_, mapped) = lookup_type_alias(ctx, mapped_file.as_str(), &mapped_name)?;
214	    let CollectedTypeAlias::Passthrough { target: CollectedType::Mapped { param, key_type, value_type, .. }, .. } =
215	        mapped
216	    else {
217	        return None;
218	    };
219	    let keys = super::evaluate::mapped_keys(key_type, &mapped_file, ctx, 0)?;
220	    if !keys.iter().any(|key| key.name == member) {
221	        return None;
222	    }
223	    let mut bindings = super::substitute::Substitution::default();
224	    bindings.insert(param.as_str(), CollectedType::StringLiteral(member.into()));
225	    let value = substitute_type(value_type, &bindings);
226	    component_props_type(&value, &mapped_file, ctx, depth + 1).map(|(props, file, _)| (props, file))
227	}
