  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    if (e.name === 'node_modules' || e.name.startsWith('.')) continue;
    const p = path.join(d, e.name);
    if (e.isDirectory() || (e.isSymbolicLink() && fs.statSync(p).isDirectory())) walk(p);
    else if (/\.tsx$/.test(p) && !/\.d\.tsx$/.test(p)) files.push(p);
  }
})(process.argv[3]);
const peel = (e) => { while (e && (ts.isParenthesizedExpression(e) || ts.isAsExpression(e) || ts.isSatisfiesExpression(e) || ts.isNonNullExpression(e))) e = e.expression; return e; };
const rows = [];
for (const f of files) {
  const src = ts.createSourceFile(f, fs.readFileSync(f, 'utf8'), ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
  const pos = new Map();
  for (const st of src.statements) {
    if (ts.isFunctionDeclaration(st) && st.name) pos.set(st.name.text, st.pos);
    else if (ts.isClassDeclaration(st) && st.name) pos.set(st.name.text, st.pos);
    else if (ts.isVariableStatement(st)) for (const d of st.declarationList.declarations) if (ts.isIdentifier(d.name)) pos.set(d.name.text, st.pos);
  }
  for (const st of src.statements) {
    if (!ts.isVariableStatement(st)) continue;
    for (const d of st.declarationList.declarations) {
      if (!ts.isIdentifier(d.name) || !/^[A-Z][a-z]/.test(d.name.text) || !d.initializer) continue;
      let init = peel(d.initializer), ref = null, kind = null;
      if (ts.isIdentifier(init)) { ref = init.text; kind = 'alias'; }
      else if (ts.isCallExpression(init) && init.arguments[0] && ts.isIdentifier(peel(init.arguments[0]))) { ref = peel(init.arguments[0]).text; kind = 'call:' + init.expression.getText().slice(0, 30); }
      if (!ref || !pos.has(ref)) continue;
      rows.push({ f: f.replace(/.*\/g3\//, ''), name: d.name.text, ref, kind, later: pos.get(ref) > st.pos });
    }
  }
}
